import React from "react"
import type { ReactNode } from "react"
import { Typography } from "@heroui/react"
/** Props for the {@link ErrorPageState} block. */
export interface ErrorPageStateProps {
    /** Large status numeral (e.g. `"404"`, `"500"`) shown at the top. */
    code: ReactNode
    /** Headline (e.g. "Page not found"). */
    title: ReactNode
    /** Optional supporting line under the title. */
    description?: ReactNode
    /** Optional actions (typically Buttons: retry / home), centered under the copy. */
    actions?: ReactNode
}

/**
 * Full-page error/empty STATE for whole-route failures ΓÇö the 404 (route not
 * found) and 500 (error boundary) pages, and the profile's own not-found. A
 * centered column: a large muted status numeral, a title + optional description,
 * and optional actions. Presentational (props-only) so it renders in both the
 * server `not-found` and the client `error` boundary; the caller supplies the
 * localized copy + wired action buttons.
 *
 * @param props - {@link ErrorPageStateProps}
 * @see Story: .storybook/stories/blocks/feedback/ErrorPageState/ErrorPageState.stories
 */
export const ErrorPageState = ({
    code,
    title,
    description,
    actions}: ErrorPageStateProps) => {
    return (
        <div
            className={"mx-auto flex min-h-[70vh] max-w-xl flex-col items-center justify-center gap-6 px-6 py-16 text-center"}
        >
            <Typography type="h1" weight="bold" color="muted">{code}</Typography>
            <div className="flex flex-col gap-2">
                <Typography type="h4" weight="semibold">{title}</Typography>
                {description ? (
                    <Typography type="body-sm" color="muted">{description}</Typography>
                ) : null}
            </div>
            {actions ? (
                <div className="flex flex-wrap items-center justify-center gap-3">{actions}</div>
            ) : null}
        </div>
    )
}

"use client"

import React from "react"
import { Button, Typography } from "@heroui/react"
import { WarningIcon } from "@phosphor-icons/react"
/** Props for {@link ErrorState}. */
export interface ErrorStateProps {
    /**
     * Primary error headline rendered emphasized below the warning icon.
     * Caller supplies a translated node (e.g. via `t()`).
     */
    title?: React.ReactNode
    /**
     * Secondary explanatory line shown muted beneath the title.
     * Caller supplies a translated node (e.g. via `t()`).
     */
    description?: React.ReactNode
    /**
     * Label for the retry button. The button only renders when both this
     * label and {@link onRetry} are provided. Caller supplies a translated node.
     */
    retryLabel?: React.ReactNode
    /**
     * Invoked when the user presses the retry button. When omitted, no retry
     * button is shown regardless of {@link retryLabel}.
     */
    onRetry?: () => void
}

/**
 * Centered, presentational error-state block: a danger-toned warning icon, an
 * optional title and description, and an optional retry button. Purely
 * props-driven (no store/fetch); text and the retry handler are supplied by the
 * caller so it stays self-contained and reusable across features.
 *
 * @param props - {@link ErrorStateProps}
 * @see Story: .storybook/stories/blocks/feedback/ErrorState/ErrorState.stories
 */
export const ErrorState = ({
    title,
    description,
    retryLabel,
    onRetry}: ErrorStateProps) => {
    return (
        <div
            className={"flex flex-col items-center gap-3 py-6 text-center"}
        >
            <WarningIcon weight="duotone" className="size-8 text-foreground" />
            {title ? (
                <Typography weight="medium">{title}</Typography>
            ) : null}
            {description ? (
                <Typography type="body-xs" color="muted">{description}</Typography>
            ) : null}
            {onRetry && retryLabel ? (
                <Button variant="secondary" size="sm" onPress={onRetry}>
                    {retryLabel}
                </Button>
            ) : null}
        </div>
    )
}

"use client"

import React from "react"
import {
    Tooltip,
    Typography,
} from "@heroui/react"
import type {
    ReactNode,
} from "react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"

/** Props for {@link InfoTooltip}. */
export interface InfoTooltipProps extends WithClassNames<undefined> {
    /** The trigger ΓÇö the term / chip / label the tooltip explains. */
    children: ReactNode
    /** Bold heading line (e.g. the term itself). Omit for description-only. */
    title?: string
    /** The plain-language explanation. Ignored when {@link content} is given. */
    description?: string
    /**
     * Full custom body, overriding {@link title}/{@link description} ΓÇö for richer
     * tooltips (multiple lines, highlighted values). Compose with `Typography`.
     */
    content?: ReactNode
    /** Tooltip placement relative to the trigger. Defaults to "top". */
    placement?: "top" | "bottom" | "left" | "right"
}

/**
 * InfoTooltip ΓÇö the single way to attach a plain-language explanation to a hard
 * term (rank, tier, KPI, streak, leagueΓÇª). Wraps any trigger in a HeroUI Tooltip
 * and OWNS all the tooltip chrome (inset, max-width, arrow), so features pass only
 * a `title`/`description` (or a composed `content`) and the trigger as children.
 *
 * The trigger keeps a `cursor-help` affordance so it reads as "hover for more".
 *
 * @param props - {@link InfoTooltipProps}
 * @see Story: .storybook/stories/blocks/feedback/InfoTooltip/InfoTooltip.stories
 */
export const InfoTooltip = ({
    children,
    title,
    description,
    content,
    placement = "top",
    className,
}: InfoTooltipProps) => {
    return (
        <Tooltip delay={200}>
            <Tooltip.Trigger className={className}>
                <span className="inline-flex cursor-help">
                    {children}
                </span>
            </Tooltip.Trigger>
            <Tooltip.Content
                placement={placement}
                showArrow
                className="max-w-[260px]"
            >
                <Tooltip.Arrow />
                <div className="flex flex-col gap-1">
                    {content ?? (
                        <>
                            {title ? (
                                <Typography type="body-sm">
                                    {title}
                                </Typography>
                            ) : null}
                            {description ? (
                                <Typography type="body-xs" color="muted">
                                    {description}
                                </Typography>
                            ) : null}
                        </>
                    )}
                </div>
            </Tooltip.Content>
        </Tooltip>
    )
}

import React from "react"
import { cn } from "@heroui/react"
import type { ReactNode } from "react"

import type { WithClassNames } from "@/modules/types/base/class-name"

/**
 * Props for the {@link SimpleEmptyState} block.
 */
export interface SimpleEmptyStateProps extends WithClassNames<undefined> {
    /**
     * Translated copy explaining why the area is empty. The caller supplies
     * the message ΓÇö this block never calls a translation hook itself.
     */
    children: ReactNode
}

/**
 * Minimal inline empty-state message: a single muted, small line of text.
 *
 * Use this for lightweight "nothing here yet" placeholders inside a tab or
 * panel body. For a richer placeholder with an icon, title, description, and
 * action, use {@link EmptyState} instead.
 *
 * @param props - See {@link SimpleEmptyStateProps}.
 * @returns The rendered empty-state element.
 * @see Story: .storybook/stories/blocks/feedback/SimpleEmptyState/SimpleEmptyState.stories
 */
export const SimpleEmptyState = ({ children, className }: SimpleEmptyStateProps) => {
    return (
        <p className={cn("text-sm text-muted", className)}>
            {children}
        </p>
    )
}

"use client"

import React from "react"
import { Typography, cn } from "@heroui/react"

/** The kind of a diff line: an addition, a deletion, or unchanged context. */
export type DiffLineType = "add" | "del" | "ctx"

/** One pre-parsed line of a diff. The caller does the diffing; this block only renders. */
export interface DiffLine {
    /** Whether the line was added, removed, or is unchanged context. */
    type: DiffLineType
    /** The raw text content of the line (without the leading +/-/space marker). */
    content: string
    /** Line number in the OLD file. Omit for pure additions. */
    oldNumber?: number
    /** Line number in the NEW file. Omit for pure deletions. */
    newNumber?: number
}

/** A contiguous group of diff lines, optionally introduced by a hunk header. */
export interface DiffHunk {
    /** Optional hunk header (e.g. "@@ -1,4 +1,5 @@" or a section label). */
    header?: string
    /** The pre-parsed lines that make up this hunk. */
    lines: DiffLine[]
}

/** How the diff is laid out. */
export type DiffViewerVariant = "unified" | "split"

/**
 * Props for the {@link DiffViewer} block.
 *
 * Tier-3 presentational: props-only, no store/SWR/fetch, and no diff ALGORITHM ΓÇö
 * the caller supplies already-parsed hunks. Used for grading feedback that
 * compares student code against a suggested fix.
 */
export interface DiffViewerProps {
    /** Optional filename shown in the header bar above the diff (e.g. "src/auth.ts"). */
    filename?: string
    /** The pre-parsed hunks to render, in order. */
    hunks: DiffHunk[]
    /**
     * Layout variant. `"unified"` (default) stacks all lines in a single column;
     * `"split"` places the old file on the left and the new file on the right.
     */
    variant?: DiffViewerVariant
}

/** type ΓåÆ row background + text color classes (tokens only). */
const LINE_TONE: Record<DiffLineType, string> = {
    add: "bg-success-soft text-success-soft-foreground",
    del: "bg-danger-soft text-danger-soft-foreground",
    ctx: "text-foreground",
}

/** type ΓåÆ the leading marker glyph in the unified gutter. */
const LINE_MARKER: Record<DiffLineType, string> = {
    add: "+",
    del: "-",
    ctx: " ",
}

/** Props for {@link NumberCell}. */
interface NumberCellProps {
    /** Line number to show; omit / undefined renders an empty gutter cell. */
    value?: number
}

/** A monospace line-number cell in the gutter (right-aligned, non-selectable). */
const NumberCell = ({ value }: NumberCellProps) => (
    <span className="w-10 shrink-0 select-none pr-2 text-right tabular-nums text-muted-foreground">
        {value ?? ""}
    </span>
)

/** Props for {@link UnifiedRow}. */
interface UnifiedRowProps {
    /** Pre-parsed diff line to render. */
    line: DiffLine
}

/** One rendered line in the UNIFIED layout: [old #][new #][marker][content]. */
const UnifiedRow = ({ line }: UnifiedRowProps) => (
    <div className={cn("flex items-start", LINE_TONE[line.type])}>
        <NumberCell value={line.oldNumber} />
        <NumberCell value={line.newNumber} />
        <span className="w-4 shrink-0 select-none text-center">
            {LINE_MARKER[line.type]}
        </span>
        <span className="whitespace-pre pr-4">{line.content}</span>
    </div>
)

/** Props for {@link SplitCell}. */
interface SplitCellProps {
    /** Line for this side, or `null` for a blank filler cell. */
    line: DiffLine | null
    /** Which file side this cell represents. */
    side: "old" | "new"
}

/** One side of the SPLIT layout: a single line number + content, or a blank filler row. */
const SplitCell = ({ line, side }: SplitCellProps) => (
    <div
        className={cn(
            "flex items-start",
            // A filler cell (no line on this side) stays neutral; a real line gets its tone.
            line ? LINE_TONE[line.type] : "text-foreground",
        )}
    >
        <NumberCell value={side === "old" ? line?.oldNumber : line?.newNumber} />
        <span className="whitespace-pre pr-4">{line ? line.content : ""}</span>
    </div>
)

/**
 * DiffViewer renders a code diff for grading feedback ΓÇö student code versus a
 * suggested fix. It accepts PRE-PARSED hunks (no diff algorithm lives here) and
 * shows a filename header bar, a line-number gutter, and token-colored line
 * backgrounds: additions use `bg-success-soft`, deletions `bg-danger-soft`, and
 * context stays neutral. Long lines never break the page ΓÇö the code area scrolls
 * horizontally inside its own `overflow-x-auto` container.
 *
 * `variant="unified"` (default) stacks every line in one column with +/-/space
 * markers. `variant="split"` places the old file on the left and the new file on
 * the right; each source line lands on its own side while context appears on both.
 *
 * Tier-3 presentational block: props-only, no store, no SWR, no side-effects.
 *
 * @param props - {@link DiffViewerProps}
 *
 * @example
 * <DiffViewer
 *     filename="src/auth.ts"
 *     hunks={[{ header: "@@ -1,3 +1,4 @@", lines: [
 *         { type: "ctx", content: "function login() {", oldNumber: 1, newNumber: 1 },
 *         { type: "del", content: "  return true", oldNumber: 2 },
 *         { type: "add", content: "  return verify(token)", newNumber: 2 },
 *     ] }]}
 * />
 * @see Story: .storybook/stories/blocks/grading/DiffViewer/DiffViewer.stories
 */
export const DiffViewer = ({
    filename,
    hunks,
    variant = "unified"}: DiffViewerProps) => {
    return (
        <div
            className={cn(
                "overflow-hidden rounded-xl border border-default bg-surface")}
        >
            {/* Filename header bar ΓÇö sits above the scrollable code area */}
            {filename ? (
                <div className="border-b border-default bg-default px-4 py-2">
                    <Typography type="body-sm" weight="medium" className="font-mono">
                        {filename}
                    </Typography>
                </div>
            ) : null}

            {/* Horizontal-scroll container so long lines never break the page */}
            <div className="overflow-x-auto">
                <div className="min-w-fit py-1 font-mono text-xs leading-relaxed">
                    {hunks.map((hunk, hunkIndex) => (
                        <div key={hunkIndex}>
                            {/* Optional hunk header ΓÇö muted separator row */}
                            {hunk.header ? (
                                <div className="whitespace-pre bg-default px-4 py-1 text-muted-foreground">
                                    {hunk.header}
                                </div>
                            ) : null}

                            {variant === "split"
                                ? hunk.lines.map((line, lineIndex) => (
                                    <div
                                        key={lineIndex}
                                        className="grid grid-cols-2 divide-x divide-default"
                                    >
                                        {/* Old side hides pure additions; new side hides pure deletions */}
                                        <SplitCell
                                            line={line.type === "add" ? null : line}
                                            side="old"
                                        />
                                        <SplitCell
                                            line={line.type === "del" ? null : line}
                                            side="new"
                                        />
                                    </div>
                                ))
                                : hunk.lines.map((line, lineIndex) => (
                                    <UnifiedRow key={lineIndex} line={line} />
                                ))}
                        </div>
                    ))}
                </div>
            </div>
        </div>
    )
}

import { CaretDownIcon, LockIcon, SparkleIcon, WarningCircleIcon, WarningIcon } from "@phosphor-icons/react"
import React, { useMemo, useState } from "react"
import {
    Button,
    Chip,
    Dropdown,
    DropdownItem,
    DropdownMenu,
    DropdownPopover,
    DropdownSection,
    DropdownTrigger,
    ScrollShadow,
    SearchField,
    Separator,
    Tooltip,
    Typography,
    cn
} from "@heroui/react"
import { ModelProvider } from "@/modules/api/graphql/queries/query-my-ai-settings"
import { AiModelCategory, AiModelTask } from "@/modules/api/graphql/queries/query-ai-models"
import { type AiGradableModel } from "@/modules/api/graphql/queries/types/ai-models"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { AiCategoryChip } from "@/components/blocks/chips/AiCategoryChip"
import { SelfHostGpuMark } from "@/components/blocks/grading/SelfHostGpuMark"
import { FlexWrapButtonRadio } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import type { ModelHealth } from "@/hooks/socketio/useAiModelLatency"

/**
 * Model selection emitted by the picker. `model`/`provider` null = the Auto
 * lane (the balancer picks); a pinned model runs on that model. Structurally
 * matches feature selection types (e.g. ChallengeGradeSelection) so callers
 * pass theirs directly.
 */
export interface GradeModelSelection {
    /** Pinned model name, or null for the Auto lane. */
    model: string | null
    /** Provider of the pinned model, or null for the Auto lane. */
    provider: ModelProvider | null
}

/** Categories that need an unlock (paid OR enrolled) to pick. */
const PLAN_CATEGORIES: ReadonlyArray<AiModelCategory> = [
    AiModelCategory.Medium,
    AiModelCategory.High,
]

/** Category ladder cheapest ΓåÆ strongest ΓÇö for "below the floor" comparison. */
const CATEGORY_ORDER: ReadonlyArray<AiModelCategory> = [
    AiModelCategory.Low,
    AiModelCategory.Medium,
    AiModelCategory.High,
]

/** Tier facet options (incl. the "all" reset). */
export const TIER_FILTERS: ReadonlyArray<AiModelCategory | "all"> = [
    "all",
    AiModelCategory.Low,
    AiModelCategory.Medium,
    AiModelCategory.High,
]

/**
 * Live health badge on each model row ΓÇö a green dot + latency (up) or a red dot
 * + "down" (failing probe), styled like the category chip. Driven by the public
 * `aiModelLatency` snapshot + `/system_health` socket; rendered only when data exists.
 */
const ModelHealthChip = ({ ok, errorMessage, latencyLabel, downLabel }: ModelHealth & { latencyLabel: string, downLabel: string }) => {
    const chip = (
        <Chip
            color={ok ? "success" : "danger"}
            variant="soft"
            size="sm"
        >
            <span className={cn("size-1.5 rounded-full", ok ? "bg-success" : "bg-danger")} />
            <Chip.Label>
                {ok ? latencyLabel : downLabel}
            </Chip.Label>
        </Chip>
    )

    if (!ok && errorMessage) {
        return (
            <Tooltip>
                <Tooltip.Trigger className="shrink-0 cursor-default">
                    {chip}
                </Tooltip.Trigger>
                <Tooltip.Content>{errorMessage}</Tooltip.Content>
            </Tooltip>
        )
    }

    return <span className="shrink-0">{chip}</span>
}

/**
 * A model served by the `local` provider runs on StarCi GPU hardware by
 * definition, so the provider alone decides the mark.
 */
const showSelfHostMark = (model: AiGradableModel) =>
    model.provider === ModelProvider.Local

/** Dropdown row width ΓÇö popover must be bounded or `truncate` never fires. */
const DROPDOWN_POPOVER_CLASS = "w-80 max-w-[calc(100vw-2rem)]"
const DROPDOWN_ITEM_ROW_CLASS = "w-full min-w-0 overflow-hidden"

/**
 * HeroUI's `Select.Indicator` chevron, replicated 1:1 (same 16├ù16 viewBox + path)
 * so the `isDropdown` trigger's caret is IDENTICAL to the Select dropdowns beside
 * it ΓÇö `IconChevronDown` is a HeroUI internal, not exported, so we inline its SVG.
 */
const FieldChevronDown = () => (
    <svg aria-hidden="true" fill="none" viewBox="0 0 16 16" className="size-4">
        <path
            clipRule="evenodd"
            fillRule="evenodd"
            fill="currentColor"
            d="M2.97 5.47a.75.75 0 0 1 1.06 0L8 9.44l3.97-3.97a.75.75 0 1 1 1.06 1.06l-4.5 4.5a.75.75 0 0 1-1.06 0l-4.5-4.5a.75.75 0 0 1 0-1.06"
        />
    </svg>
)
const MODEL_ROW_TRIGGER_CLASS = "block w-full min-w-0"

/** Props for {@link ModelRowLayout}. */
interface ModelRowLayoutProps {
    leading?: React.ReactNode
    name: string
    nameSuffix?: React.ReactNode
    isSelected?: boolean
    muted?: boolean
    trailing: React.ReactNode
}

/** Model row ΓÇö name truncates on the left, chips stay pinned on the right. */
const ModelRowLayout = ({
    leading,
    name,
    nameSuffix,
    isSelected,
    muted,
    trailing,
}: ModelRowLayoutProps) => (
    <div
        className={cn(
            "grid w-full grid-cols-[minmax(0,1fr)_auto] items-center gap-2",
            muted && "text-muted",
        )}
    >
        <span className="flex min-w-0 items-center gap-2 overflow-hidden">
            {leading}
            <span
                className={cn("min-w-0 truncate", isSelected && "text-accent-soft-foreground")}
                title={name}
            >
                {name}
            </span>
            {nameSuffix}
        </span>
        <span className="flex shrink-0 items-center justify-end gap-2">{trailing}</span>
    </div>
)

/** Props for {@link GradeModelDropdown}. */
export type GradeModelDropdownProps = WithClassNames<undefined> & {
    /** Enabled models the user can pick from (from the `aiModels` catalog). */
    models: Array<AiGradableModel>
    /** The current lane + model selection. */
    selection: GradeModelSelection
    /** Whether higher-tier models are unlocked for this user (paid OR enrolled). */
    canPremium: boolean
    /** Disables the whole control (e.g. while a grade is in flight). */
    isDisabled?: boolean
    /** Show the "Auto" lane entry on top. Default true. */
    showAutoLane?: boolean
    /** Recommended minimum category. Any model BELOW it is flagged WARNING. */
    floor?: AiModelCategory
    /** Only show models suited for this task (chatting / grading). */
    task?: AiModelTask
    /** Popover placement. Default "bottom start"; pass "top start" for a bottom-anchored composer. */
    placement?: "bottom start" | "top start"
    /** Render the trigger as a standard bordered field-style dropdown button. */
    isDropdown?: boolean
    /** Render the trigger as a real `Button` (`variant="tertiary"`). */
    isButton?: boolean
    /** `isButton` only ΓÇö stretch the trigger `Button` to the full width of its container. */
    isButtonFullWidth?: boolean
    /** Fired with the new selection when the user picks an option. */
    onSelect: (selection: GradeModelSelection) => void
    /** Fired when a locked (unlock-required) model is pressed ΓÇö route to plans. */
    onUpgrade: () => void
    /** Live per-model health (dot + latency chip on each row); empty until the BE ships it. */
    latency: Map<string, ModelHealth>
    /** Already-localized "Auto" lane title (used as both the entry label and the fallback trigger label). */
    autoLaneLabel: string
    /** Already-localized "pick a model" trigger fallback (Auto lane hidden, nothing picked yet). */
    pickModelLabel: string
    /** Already-localized model-search field placeholder/aria-label. */
    searchModelLabel: string
    /** Already-localized "no models match" empty-search row label. */
    searchModelEmptyLabel: string
    /** Already-localized tier-filter aria-label. */
    filterTierLabel: string
    /** Already-localized "All" tier-filter option label. */
    filterAllLabel: string
    /** Already-localized tier label per category (for the inline tier filter + tooltips). */
    tierLabels: Record<AiModelCategory, string>
    /** Already-localized "model unavailable" tooltip text. */
    modelUnavailableLabel: string
    /** Already-localized "subscribe to unlock" tooltip text. */
    subscribeToGradeLabel: string
    /** Already-localized below-floor warning tooltip text. */
    belowFloorWarningLabel: string
    /** Already-localized off-task warning tooltip text. */
    offTaskWarningLabel: string
    /** Already-localized "hide hidden models" toggle label. */
    hideHiddenModelsLabel: string
    /** Already-localized, count-bound "show N hidden models" toggle label. */
    showHiddenModelsLabel: (count: number) => string
    /** Already-localized, ms-bound live-latency chip label. */
    latencyLabel: (ms: number) => string
    /** Already-localized "down" health-chip label. */
    downLabel: string
}

/**
 * Shared lane + model picker (grading, AI lab, any model-select surface).
 *
 * Renders the "Auto" lane plus every catalog model (tagged with its cost
 * category chip). Per model:
 * - no working key ΓåÆ DISABLED (warning, not selectable).
 * - Balanced / Premium / Frontier without an unlock ΓåÆ LOCKED (routes to plans).
 * - below the `floor` ΓåÆ SELECTABLE but flagged WARNING (may be inaccurate).
 * - otherwise ΓåÆ normal selectable.
 *
 * @param props - {@link GradeModelDropdownProps}
 */
export const _GradeModelDropdown = ({
    models,
    selection,
    canPremium,
    isDisabled = false,
    showAutoLane = true,
    floor,
    task,
    placement = "bottom start",
    isDropdown,
    isButton = false,
    isButtonFullWidth = false,
    onSelect,
    onUpgrade,
    latency,
    autoLaneLabel,
    pickModelLabel,
    searchModelLabel,
    searchModelEmptyLabel,
    filterTierLabel,
    filterAllLabel,
    tierLabels,
    modelUnavailableLabel,
    subscribeToGradeLabel,
    belowFloorWarningLabel,
    offTaskWarningLabel,
    hideHiddenModelsLabel,
    showHiddenModelsLabel,
    latencyLabel,
    downLabel,
    className,
}: GradeModelDropdownProps) => {
    // controlled open so selecting Auto can close the popover on press.
    const [isOpen, setIsOpen] = useState(false)
    const [query, setQuery] = useState("")
    const normalizedQuery = query.trim().toLowerCase()
    // single inline facet: tier.
    const [tierFilter, setTierFilter] = useState<AiModelCategory | "all">("all")
    // down (unavailable) + off-task models are HIDDEN by default; `showHidden` reveals them.
    const [showHidden, setShowHidden] = useState(false)
    const { visibleModels, hiddenCount } = useMemo(() => {
        const visible: Array<AiGradableModel> = []
        let hidden = 0
        for (const model of models) {
            if (normalizedQuery
                && !model.model.toLowerCase().includes(normalizedQuery)) {
                continue
            }
            if (tierFilter !== "all" && model.category !== tierFilter) {
                continue
            }
            const offTask = Boolean(task
                && model.supportedTasks?.length
                && !model.supportedTasks.includes(task))
            if (!model.available || offTask) {
                hidden += 1
                if (!showHidden) {
                    continue
                }
            }
            visible.push(model)
        }
        return { visibleModels: visible, hiddenCount: hidden }
    }, [models, normalizedQuery, tierFilter, task, showHidden])
    // tiers present in the catalog ΓåÆ the inline tier filter only offers real buckets.
    const tierChips = useMemo(() => {
        const present = new Set(models.map((model) => model.category))
        return TIER_FILTERS.filter((tier) => tier === "all" || present.has(tier))
    }, [models])
    // a pinned model shows its name; otherwise the Auto label (or "pick a model"
    // when the Auto lane is hidden and nothing is picked yet)
    const triggerLabel = selection.model
        ?? (showAutoLane ? autoLaneLabel : pickModelLabel)

    return (
        <Dropdown
            isOpen={isOpen}
            onOpenChange={(open) => {
                setIsOpen(open)
                if (!open) {
                    setQuery("")
                    setTierFilter("all")
                    setShowHidden(false)
                }
            }}
        >
            {isButton ? (
                <DropdownTrigger
                    isDisabled={isDisabled}
                    className={cn("cursor-pointer", isButtonFullWidth && "block w-full", className)}
                >
                    <Button variant="tertiary" size="sm" fullWidth={isButtonFullWidth}>
                        <SparkleIcon aria-hidden className="size-4 shrink-0" />
                        <span className={cn("truncate", isButtonFullWidth ? "min-w-0 flex-1 text-left" : "max-w-40")}>
                            {triggerLabel}
                        </span>
                    </Button>
                </DropdownTrigger>
            ) : isDropdown ? (
                <DropdownTrigger
                    isDisabled={isDisabled}
                    className={cn(
                        "relative flex! min-h-9 w-full cursor-pointer items-center rounded-field border border-[color:var(--field-border)] bg-field py-2 pe-7 ps-3 text-sm text-field-foreground shadow-field transform-none!",
                        "hover:bg-field-hover hover:border-[color:var(--field-border-hover)]",
                        "data-[hovered=true]:bg-field-hover data-[hovered=true]:border-[color:var(--field-border-hover)]",
                        "data-[focus-visible=true]:border-[color:var(--field-border-focus)]",
                        className,
                    )}
                >
                    <span className="flex min-w-0 items-center gap-2 overflow-hidden">
                        <SparkleIcon className="size-4 shrink-0" />
                        <span className="truncate">{triggerLabel}</span>
                    </span>
                    <span
                        className={cn(
                            "absolute inset-y-0 end-2 my-auto flex shrink-0 items-center justify-center text-field-placeholder transition duration-150",
                            isOpen && "rotate-180",
                        )}
                    >
                        <FieldChevronDown />
                    </span>
                </DropdownTrigger>
            ) : (
                <DropdownTrigger
                    isDisabled={isDisabled}
                    className={cn("min-w-0 max-w-full cursor-pointer", className)}
                >
                    <div className="flex w-full min-w-0 items-center justify-between gap-2">
                        <span className="flex min-w-0 items-center gap-2 overflow-hidden">
                            <SparkleIcon className="size-4 shrink-0" />
                            <span className="truncate">{triggerLabel}</span>
                        </span>
                        <CaretDownIcon weight="bold" className="size-4 shrink-0" />
                    </div>
                </DropdownTrigger>
            )}
            <DropdownPopover
                placement={placement}
                className={DROPDOWN_POPOVER_CLASS}
            >
                <div className="flex w-full min-w-0 flex-col">
                    {/* Auto lane ΓÇö above search + scroll so the default is always one click away. */}
                    {showAutoLane ? (
                        <>
                            <DropdownMenu aria-label={autoLaneLabel}>
                                <DropdownSection>
                                    <DropdownItem
                                        key="auto"
                                        textValue={autoLaneLabel}
                                        onPress={() => {
                                            onSelect({
                                                model: null,
                                                provider: null,
                                            })
                                            setIsOpen(false)
                                        }}
                                    >
                                        <div
                                            className={cn(
                                                "flex items-center gap-2",
                                                !selection.model && "text-accent-soft-foreground",
                                            )}
                                        >
                                            <SparkleIcon className="size-4 shrink-0" />
                                            <span>{autoLaneLabel}</span>
                                        </div>
                                    </DropdownItem>
                                </DropdownSection>
                                <Separator />
                            </DropdownMenu>
                        </>
                    ) : null}
                    {/* Search ΓåÆ inline tier filter ΓåÆ list, separated by whitespace only
                    (no divider, no funnel panel). down + off-task hidden by default. */}
                    <div
                        className="px-2"
                        onKeyDownCapture={(event) => event.stopPropagation()}
                    >
                        <SearchField
                            variant="secondary"
                            aria-label={searchModelLabel}
                        >
                            <SearchField.Group>
                                <SearchField.SearchIcon />
                                <SearchField.Input
                                    placeholder={searchModelLabel}
                                    value={query}
                                    onChange={(event) => setQuery(event.target.value)}
                                />
                                {query ? (
                                    <SearchField.ClearButton onPress={() => setQuery("")} />
                                ) : null}
                            </SearchField.Group>
                        </SearchField>
                    </div>
                    {/* tier filter ΓÇö FlexWrapButtonRadio inside popover surface */}
                    {tierChips.length > 1 ? (
                        <div className="px-2 pt-2">
                            <FlexWrapButtonRadio
                                ariaLabel={filterTierLabel}
                                value={tierFilter}
                                onChange={setTierFilter}
                                items={tierChips.map((tier) => ({
                                    value: tier,
                                    content: tier === "all"
                                        ? filterAllLabel
                                        : tierLabels[tier],
                                }))}
                            />
                        </div>
                    ) : null}
                    <ScrollShadow
                        hideScrollBar
                        className="max-h-72 w-full min-w-0"
                    >
                        <DropdownMenu
                            aria-label={pickModelLabel}
                            className="w-full min-w-0"
                        >
                            {/* One entry per catalog model. Below-floor = warning (selectable,
                        risky); Balanced/Premium/Frontier = locked without an unlock. */}
                            <DropdownSection>
                                {visibleModels.length === 0 ? (
                                    <DropdownItem
                                        key="no-results"
                                        textValue={searchModelEmptyLabel}
                                        onPress={() => undefined}
                                    >
                                        <span className="text-muted">{searchModelEmptyLabel}</span>
                                    </DropdownItem>
                                ) : null}
                                {visibleModels.map((model) => {
                                    const key = `${model.provider}:${model.model}`
                                    const isSelected = selection.model === model.model
                                        && selection.provider === model.provider
                                    const categoryChip = <AiCategoryChip category={model.category} />
                                    // live health (right of the category chip); null until probe data arrives
                                    const health = latency.get(model.model)
                                    const healthChip = health
                                        ? (
                                            <ModelHealthChip
                                                ok={health.ok}
                                                latencyMs={health.latencyMs}
                                                errorMessage={health.errorMessage}
                                                latencyLabel={latencyLabel(health.latencyMs)}
                                                downLabel={downLabel}
                                            />
                                        )
                                        : null
                                    const selfHostMark = showSelfHostMark(model) ? <SelfHostGpuMark /> : null
                                    const requiresPlan = PLAN_CATEGORIES.includes(model.category)
                                    // below the recommended floor ΓåÆ flag danger (grading: Free is
                                    // below Economy). No floor ΓåÆ never flagged (chatbot runs Free).
                                    const belowFloor = floor !== undefined
                                        && CATEGORY_ORDER.indexOf(model.category) < CATEGORY_ORDER.indexOf(floor)
                                    // not suited for this picker's task ΓåÆ amber warning
                                    const offTask = Boolean(task
                                        && model.supportedTasks?.length
                                        && !model.supportedTasks.includes(task))
                                    if (!model.available) {
                                        return (
                                            <DropdownItem
                                                key={key}
                                                textValue={model.model}
                                                className={DROPDOWN_ITEM_ROW_CLASS}
                                                onPress={() => undefined}
                                            >
                                                <Tooltip>
                                                    <Tooltip.Trigger className={MODEL_ROW_TRIGGER_CLASS}>
                                                        <ModelRowLayout
                                                            muted
                                                            name={model.model}
                                                            nameSuffix={selfHostMark}
                                                            leading={<WarningCircleIcon className="size-5 shrink-0" />}
                                                            trailing={<>{healthChip}{categoryChip}</>}
                                                        />
                                                    </Tooltip.Trigger>
                                                    <Tooltip.Content>{modelUnavailableLabel}</Tooltip.Content>
                                                </Tooltip>
                                            </DropdownItem>
                                        )
                                    }
                                    if (requiresPlan && !canPremium) {
                                        return (
                                            <DropdownItem
                                                key={key}
                                                textValue={model.model}
                                                className={DROPDOWN_ITEM_ROW_CLASS}
                                                onPress={onUpgrade}
                                            >
                                                <Tooltip>
                                                    <Tooltip.Trigger className={MODEL_ROW_TRIGGER_CLASS}>
                                                        <ModelRowLayout
                                                            muted
                                                            name={model.model}
                                                            nameSuffix={selfHostMark}
                                                            leading={<LockIcon className="size-5 shrink-0" />}
                                                            trailing={<>{healthChip}{categoryChip}</>}
                                                        />
                                                    </Tooltip.Trigger>
                                                    <Tooltip.Content>
                                                        <Typography type="body-sm">{subscribeToGradeLabel}</Typography>
                                                    </Tooltip.Content>
                                                </Tooltip>
                                            </DropdownItem>
                                        )
                                    }
                                    if (belowFloor || offTask) {
                                        return (
                                            <DropdownItem
                                                key={key}
                                                textValue={model.model}
                                                className={DROPDOWN_ITEM_ROW_CLASS}
                                                onPress={() => onSelect({
                                                    model: model.model,
                                                    provider: model.provider,
                                                })}
                                            >
                                                <Tooltip>
                                                    <Tooltip.Trigger className={MODEL_ROW_TRIGGER_CLASS}>
                                                        <ModelRowLayout
                                                            isSelected={isSelected}
                                                            name={model.model}
                                                            nameSuffix={selfHostMark}
                                                            leading={<WarningIcon className="size-5 shrink-0 text-warning-soft-foreground" />}
                                                            trailing={<>{healthChip}{categoryChip}</>}
                                                        />
                                                    </Tooltip.Trigger>
                                                    <Tooltip.Content>
                                                        <Typography type="body-sm" className="text-warning-soft-foreground">
                                                            {belowFloor
                                                                ? belowFloorWarningLabel
                                                                : offTaskWarningLabel}
                                                        </Typography>
                                                    </Tooltip.Content>
                                                </Tooltip>
                                            </DropdownItem>
                                        )
                                    }
                                    return (
                                        <DropdownItem
                                            key={key}
                                            textValue={model.model}
                                            className={DROPDOWN_ITEM_ROW_CLASS}
                                            onPress={() => onSelect({
                                                model: model.model,
                                                provider: model.provider,
                                            })}
                                        >
                                            <ModelRowLayout
                                                isSelected={isSelected}
                                                name={model.model}
                                                nameSuffix={selfHostMark}
                                                trailing={<>{healthChip}{categoryChip}</>}
                                            />
                                        </DropdownItem>
                                    )
                                })}
                            </DropdownSection>
                        </DropdownMenu>
                    </ScrollShadow>
                    {/* escape hatch ΓÇö reveal the down / off-task models hidden by default */}
                    {hiddenCount > 0 ? (
                        <button
                            type="button"
                            onClick={() => setShowHidden((open) => !open)}
                            className="cursor-pointer px-3 pb-2 pt-1 text-start text-xs text-muted transition-colors hover:text-foreground"
                        >
                            {showHidden
                                ? hideHiddenModelsLabel
                                : showHiddenModelsLabel(hiddenCount)}
                        </button>
                    ) : null}
                </div>
            </DropdownPopover>
        </Dropdown>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { cn, Typography } from "@heroui/react"

/**
 * Visual tone of a {@link NotificationItem}. Drives ONLY the color of the
 * leading icon tile (never a `bg-<status>/10` overlay ΓÇö soft tokens only), so a
 * notification kind can read at a glance:
 * - `default` ΓÇö neutral system / informational message
 * - `success` ΓÇö a positive outcome (a submission graded as passing, a certificate issued)
 * - `warning` ΓÇö an at-risk nudge (a streak-maintenance reminder, an approaching deadline)
 * - `accent` ΓÇö a brand / opportunity event (a new course opening, someone replied)
 */
export type NotificationTone = "default" | "success" | "warning" | "accent"

/** Props for {@link NotificationItem}. */
export interface NotificationItemProps {
    /**
     * Primary line describing what happened. Rendered medium-weight foreground
     * and clamped to two lines. The caller localizes it (pass a `t()` result).
     */
    title: ReactNode
    /**
     * Optional secondary detail line beneath the title, rendered smaller and
     * muted (e.g. the graded score, the replier's excerpt). Omit for a
     * title-only row.
     */
    body?: ReactNode
    /**
     * PREFORMATTED relative time string shown muted at the row's foot (e.g.
     * "2 hours ago"). The block never calls `new Date()` ΓÇö the caller supplies
     * an already-formatted, localized label.
     */
    timeLabel: ReactNode
    /**
     * Optional leading visual, typically a Phosphor icon (or a small avatar).
     * When provided it is wrapped in a rounded tile whose color derives from
     * {@link NotificationItemProps.tone}. Omit for a text-only row.
     */
    icon?: ReactNode
    /**
     * Color tone of the leading icon tile. Defaults to `"default"`. Has no
     * effect when {@link NotificationItemProps.icon} is omitted.
     */
    tone?: NotificationTone
    /**
     * When true the row reads as unread: a subtle `bg-accent-soft` tint plus an
     * accent dot beside the title. Omit / false for an already-read row.
     */
    isUnread?: boolean
    /**
     * Optional press handler. When provided the whole row becomes interactive
     * (hover surface, keyboard + screen-reader accessible). No-op-able.
     */
    onPress?: () => void
    /**
     * Optional trailing node aligned to the row's end ΓÇö typically a compact
     * action (Button / icon button) or a status chip. Kept at its intrinsic
     * size and never compresses the text column.
     */
    actionSlot?: ReactNode
}

/**
 * Maps a {@link NotificationTone} to the leading tile's background + foreground
 * token pair. Soft surface tokens only ΓÇö never a `bg-<status>/10` overlay.
 */
const TONE_TILE: Record<NotificationTone, string> = {
    default: "bg-default text-foreground",
    success: "bg-success-soft text-success-soft-foreground",
    warning: "bg-warning-soft text-warning-soft-foreground",
    accent: "bg-accent-soft text-accent-soft-foreground",
}

/**
 * NotificationItem ΓÇö one notification row on a learning platform. Lays out an
 * optional tone-colored leading icon tile, a title + optional body text column,
 * a preformatted relative-time label, an unread indicator (accent dot + subtle
 * row tint), and an optional trailing action slot. The whole row is pressable
 * when {@link NotificationItemProps.onPress} is supplied.
 *
 * Tier-3 presentational block: props-only, no store, no SWR, no side-effects.
 * The owning feature maps a notification kind to the `icon`/`tone` and passes
 * pre-formatted, localized copy and time.
 *
 * @param props - {@link NotificationItemProps}
 *
 * @example
 * <NotificationItem
 *   icon={<CheckCircleIcon />}
 *   tone="success"
 *   title="Your submission has been graded"
 *   body="API Gateway challenge ΓÇö scored 92/100"
 *   timeLabel="2 hours ago"
 *   isUnread
 *   onPress={() => {}}
 * />
 * @see Story: .storybook/stories/blocks/notifications/NotificationItem/NotificationItem.stories
 */
export const NotificationItem = ({
    title,
    body,
    timeLabel,
    icon,
    tone = "default",
    isUnread = false,
    onPress,
    actionSlot}: NotificationItemProps) => {
    const isPressable = Boolean(onPress)

    const content = (
        <>
            {icon ? (
                <span
                    className={cn("flex size-10 shrink-0 items-center justify-center rounded-2xl [&>svg]:size-5",
                        TONE_TILE[tone],
                    )}
                >
                    {icon}
                </span>
            ) : null}

            <div className="flex min-w-0 flex-1 flex-col gap-1">
                <div className="flex min-w-0 items-start gap-2">
                    {isUnread ? (
                        // accent dot ΓÇö the primary unread signal beside the title
                        <span className="mt-2 size-2 shrink-0 rounded-full bg-accent" />
                    ) : null}
                    <Typography type="body-sm" weight="medium" className="line-clamp-2">
                        {title}
                    </Typography>
                </div>
                {body ? (
                    <Typography type="body-xs" color="muted" className="line-clamp-2">
                        {body}
                    </Typography>
                ) : null}
                <Typography type="body-xs" color="muted">
                    {timeLabel}
                </Typography>
            </div>

            {actionSlot ? <div className="shrink-0">{actionSlot}</div> : null}
        </>
    )

    const baseClassName = cn(
        "flex w-full items-start gap-3 rounded-2xl p-3 text-left",
        // subtle row tint when unread ΓÇö soft token, never a status overlay
        isUnread && "bg-accent-soft",
        isPressable &&
            "transition-colors hover:bg-surface-secondary focus-visible:bg-surface-secondary focus-visible:outline-none")

    if (isPressable) {
        return (
            <div
                role="button"
                tabIndex={0}
                onClick={onPress}
                onKeyDown={(event) => {
                    if (event.key === "Enter" || event.key === " ") {
                        event.preventDefault()
                        onPress?.()
                    }
                }}
                className={cn(baseClassName, "cursor-pointer")}
            >
                {content}
            </div>
        )
    }

    return <div className={baseClassName}>{content}</div>
}

import React from "react"
import type { ReactNode } from "react"
import { Button, Typography } from "@heroui/react"
import { ChecksIcon } from "@phosphor-icons/react"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { NotificationItem } from "@/components/blocks/notifications/NotificationItem"
import type { NotificationItemProps } from "@/components/blocks/notifications/NotificationItem"

/**
 * One day-group section of a {@link NotificationList}: an optional label (e.g.
 * "Today" / "Earlier") followed by its notification rows. Omit `label` for an
 * ungrouped run of items.
 */
export interface NotificationGroup {
    /**
     * Optional section heading rendered small + muted above the group (e.g.
     * "Today", "Earlier"). Omit for an unlabeled group.
     */
    label?: ReactNode
    /** The notification rows belonging to this section, in display order. */
    items: NotificationItemProps[]
}

/** Props for {@link NotificationList}. */
export interface NotificationListProps {
    /**
     * The day-grouped sections to render, top to bottom. Each group carries an
     * optional label and its rows. When every group is empty (or the array is
     * empty) the {@link NotificationListProps.emptyState} is shown instead.
     */
    groups: NotificationGroup[]
    /**
     * Optional header title. When provided a header row renders with this title
     * and ΓÇö when {@link NotificationListProps.onMarkAllRead} is set ΓÇö a
     * "Mark all as read" text button. Omit for a bare list.
     */
    title?: ReactNode
    /**
     * Optional handler for the header's mark-all-read text button. When omitted
     * the button is not shown. No-op-able.
     */
    onMarkAllRead?: () => void
    /**
     * Optional label for the mark-all-read button. Defaults to
     * "Mark all as read". Only rendered when
     * {@link NotificationListProps.onMarkAllRead} is set.
     */
    markAllReadLabel?: ReactNode
    /**
     * Optional custom empty state shown when there are no items. Falls back to a
     * built-in {@link EmptyState} ("No notifications yet") when omitted.
     */
    emptyState?: ReactNode
}

/** Built-in fallback empty state shown when no groups carry any items. */
const DefaultEmptyState = (
    <EmptyState
        title="No notifications yet"
        description="When there's new activity in your courses, notifications show up here."
    />
)

/**
 * NotificationList ΓÇö a scrollable, optionally day-grouped list of
 * {@link NotificationItem} rows. Renders an optional header ("Notifications" + a
 * mark-all-read text button), section labels per group ("Today" / "Earlier"),
 * and an {@link EmptyState} when no items are present. The body scrolls
 * inside a capped max height so a long history never grows the container.
 *
 * Tier-3 presentational block: props-only, no store, no SWR, no side-effects.
 * The owning feature groups notifications by day and passes pre-formatted rows.
 *
 * @param props - {@link NotificationListProps}
 *
 * @example
 * <NotificationList
 *   title="Notifications"
 *   onMarkAllRead={() => {}}
 *   groups={[{ label: "Today", items: [...] }]}
 * />
 * @see Story: .storybook/stories/blocks/notifications/NotificationList/NotificationList.stories
 */
export const NotificationList = ({
    groups,
    title,
    onMarkAllRead,
    markAllReadLabel = "Mark all as read",
    emptyState}: NotificationListProps) => {
    const isEmpty = groups.every((group) => group.items.length === 0)

    return (
        <div className={"flex flex-col"}>
            {title ? (
                <div className="flex items-center justify-between gap-3 px-3 py-2">
                    <Typography type="body-sm" weight="semibold">
                        {title}
                    </Typography>
                    {onMarkAllRead ? (
                        <Button
                            size="sm"
                            variant="tertiary"
                            onPress={onMarkAllRead}
                            className="gap-2"
                        >
                            <ChecksIcon className="size-4" />
                            <Typography type="body-xs">{markAllReadLabel}</Typography>
                        </Button>
                    ) : null}
                </div>
            ) : null}

            {isEmpty ? (
                emptyState ?? DefaultEmptyState
            ) : (
                <div className="flex max-h-[420px] flex-col gap-3 overflow-y-auto p-1">
                    {groups.map((group, groupIndex) =>
                        group.items.length > 0 ? (
                            <div key={groupIndex} className="flex flex-col gap-1">
                                {group.label ? (
                                    <Typography
                                        type="body-xs"
                                        color="muted"
                                        weight="medium"
                                        className="px-3 pt-1"
                                    >
                                        {group.label}
                                    </Typography>
                                ) : null}
                                {group.items.map((item, itemIndex) => (
                                    <NotificationItem key={itemIndex} {...item} />
                                ))}
                            </div>
                        ) : null,
                    )}
                </div>
            )}
        </div>
    )
}

"use client"

import React, {
    useMemo,
    useRef,
    useState,
} from "react"
import {
    motion,
} from "framer-motion"
import {
    cn,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import type { QueryMyContributionDayData } from "@/modules/api/graphql/queries/types/my-dashboard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"

/** Props for {@link ContributionCalendarView}. */
export interface ContributionCalendarViewProps {
    /** Active contribution days for the selected year (oldest first). */
    days: Array<QueryMyContributionDayData>
    /** The year currently shown. */
    year: number
    /** Called with the picked year when the user flips the year switcher. */
    onYearChange: (year: number) => void
    /**
     * First load, nothing in hand ΓåÆ this view shimmers its own shape. The resting state
     * lives in THIS file, right beside the loaded one, and derives its counts from the
     * SAME `YEAR_SPAN` / `LEVEL_CLASS` constants ΓÇö so the two cannot drift the way a
     * hand-kept placeholder in a caller does (`loading-and-skeleton.md`).
     */
    isSkeleton?: boolean
}

/** One rendered cell of the calendar grid. */
interface HeatmapCell {
    /** Calendar day, `YYYY-MM-DD`. */
    dateStr: string
    /** Whether the day falls inside the selected year (off-year pad cells are blank). */
    inYear: boolean
    /** Total contributions that day (0 when none). */
    total: number
    /** Lessons/contents read that day. */
    contents: number
    /** Challenges passed that day. */
    challenges: number
    /** Milestone tasks passed that day. */
    milestones: number
}

/**
 * Fill per intensity level (0 = none ΓåÆ 4 = most). Theme-aware brand-pink ramp via
 * the `--heat-*` tokens (globals.css): 0 = empty track, 1ΓåÆ4 = rising activity,
 * with a distinct light/dark palette each so levels stay legible in both modes.
 */
const LEVEL_CLASS = [
    "bg-[var(--heat-0)]",
    "bg-[var(--heat-1)]",
    "bg-[var(--heat-2)]",
    "bg-[var(--heat-3)]",
    "bg-[var(--heat-4)]",
]

/** How many recent years the selector offers (current + 2 back). */
const YEAR_SPAN = 3

/**
 * Maps a day's total to an intensity level (0ΓÇô4) for the cell colour.
 * @param total - the day's contribution count.
 * @returns the intensity bucket index.
 */
const levelOf = (total: number): number => {
    // no activity ΓåÆ the empty track colour
    if (total <= 0) {
        return 0
    }
    // fixed buckets keep the scale stable across users (not relative to a max)
    if (total <= 2) {
        return 1
    }
    if (total <= 5) {
        return 2
    }
    if (total <= 9) {
        return 3
    }
    return 4
}

/**
 * Controlled, data-driven GitHub-style learning-activity heatmap ΓÇö a 7-row ├ù
 * ~53-column grid coloured by daily contributions (contents read / challenges
 * passed / milestones), with a year switcher + legend + hover popover. Pure
 * presenter: the owner supplies the `days` + selected `year` and handles
 * `onYearChange` (so it works for both the signed-in viewer's dashboard and any
 * user's public profile). `"use client"` for i18n + hover state.
 *
 * @param props - {@link ContributionCalendarViewProps}
 */
export const ContributionCalendarView = ({
    days,
    year,
    onYearChange,
    isSkeleton = false}: ContributionCalendarViewProps) => {
    const t = useTranslations()
    const locale = useLocale()

    /** Viewport box the draggable grid is constrained to (no native scroll). */
    const viewportRef = useRef<HTMLDivElement>(null)

    /** The hovered cell + its viewport anchor, driving the single shared popover. */
    const [hovered, setHovered] = useState<{
        cell: HeatmapCell
        x: number
        y: number
    } | null>(null)

    /** Recent years offered by the selector (current ΓåÆ current ΓêÆ (YEAR_SPANΓêÆ1)). */
    const years = useMemo(
        () => {
            const current = new Date().getFullYear()
            return Array.from({
                length: YEAR_SPAN,
            }).map((_, index) => current - index)
        },
        [],
    )

    /** Active-day lookup by date string (full breakdown for the hover popover). */
    const byDate = useMemo(
        () => {
            const map = new Map<string, QueryMyContributionDayData>()
            for (const day of days) {
                map.set(day.date,
                    day)
            }
            return map
        },
        [
            days,
        ],
    )

    /** Total contributions across the year (header count). */
    const totalCount = useMemo(
        () => days.reduce((sum, day) => sum + day.total,
            0),
        [
            days,
        ],
    )

    /** The year laid out as week columns (each a 7-day SunΓåÆSat array). */
    const weeks = useMemo<Array<Array<HeatmapCell>>>(
        () => {
            // align the grid start to the Sunday on/before Jan 1 (UTC, no TZ drift)
            const firstDay = new Date(Date.UTC(year,
                0,
                1))
            const cursor = new Date(firstDay)
            cursor.setUTCDate(firstDay.getUTCDate() - firstDay.getUTCDay())
            const lastDay = new Date(Date.UTC(year,
                11,
                31))
            const columns: Array<Array<HeatmapCell>> = []
            // walk week by week until the year is fully covered
            while (cursor <= lastDay) {
                const column: Array<HeatmapCell> = []
                for (let dayIndex = 0; dayIndex < 7; dayIndex += 1) {
                    const dateStr = cursor.toISOString().slice(0,
                        10)
                    // the day's counts (defaults to an empty day when absent)
                    const day = byDate.get(dateStr)
                    column.push({
                        dateStr,
                        inYear: cursor.getUTCFullYear() === year,
                        total: day?.total ?? 0,
                        contents: day?.contents ?? 0,
                        challenges: day?.challenges ?? 0,
                        milestones: day?.milestones ?? 0,
                    })
                    cursor.setUTCDate(cursor.getUTCDate() + 1)
                }
                columns.push(column)
            }
            return columns
        },
        [
            year,
            byDate,
        ],
    )

    /** Short month label per week column (only at the week a new month starts). */
    const monthLabels = useMemo(
        () => weeks.map((column, index) => {
            // anchor on the first in-year day of the column
            const firstInYear = column.find((cell) => cell.inYear)
            if (!firstInYear) {
                return ""
            }
            const month = new Date(`${firstInYear.dateStr}T00:00:00Z`).getUTCMonth()
            // previous column's month, to detect a change
            const previous = weeks[index - 1]?.find((cell) => cell.inYear)
            const previousMonth = previous
                ? new Date(`${previous.dateStr}T00:00:00Z`).getUTCMonth()
                : -1
            if (month === previousMonth) {
                return ""
            }
            return new Date(Date.UTC(year,
                month,
                1)).toLocaleDateString(locale,
                {
                    month: "short",
                })
        }),
        [
            weeks,
            year,
            locale,
        ],
    )

    /** Weekday labels shown on the left (Mon / Wed / Fri rows). */
    const weekdayLabels = useMemo(
        () => [1,
            3,
            5].map((dayIndex) => ({
            dayIndex,
            // 2025-06-01 is a Sunday ΓåÆ +dayIndex lands on the wanted weekday
            label: new Date(Date.UTC(2025,
                5,
                1 + dayIndex)).toLocaleDateString(locale,
                {
                    weekday: "short",
                }),
        })),
        [
            locale,
        ],
    )

    // The resting state of THIS view, beside the loaded one, so a change to either is
    // visible against the other. The counts come from the SAME constants the real render
    // walks (`years` from YEAR_SPAN, `LEVEL_CLASS`), so they cannot fall out of step.
    if (isSkeleton) {
        return (
            <div className={"flex flex-col gap-3"}>
                {/* header: year-scoped count + the year switcher */}
                <div className="flex items-center justify-between gap-3">
                    <Skeleton.Typography type="body-sm" width="1/3" />
                    <div className="flex items-center gap-2">
                        {years.map((option) => (
                            <Skeleton key={option} className="h-5 w-10 shrink-0 rounded-medium" />
                        ))}
                    </div>
                </div>
                {/* the heatmap grid */}
                <Skeleton className="h-40 w-full rounded-xl" />
                {/* legend: Less ΓåÆ More */}
                <div className="flex items-center justify-end gap-2">
                    <Skeleton className="h-3 w-8 shrink-0 rounded" />
                    {LEVEL_CLASS.map((_levelClass, index) => (
                        <Skeleton key={index} className="size-3 shrink-0 rounded-sm" />
                    ))}
                    <Skeleton className="h-3 w-8 shrink-0 rounded" />
                </div>
            </div>
        )
    }

    return (
        <div className={"flex flex-col gap-3"}
        >
            {/* header: year-scoped count + the year switcher */}
            <div className="flex items-center justify-between gap-3">
                <div className="text-sm text-muted">
                    {t("dashboard.contributions.title",
                        {
                            count: totalCount,
                            year,
                        })}
                </div>
                <div className="flex items-center gap-2">
                    {years.map((option) => (
                        <button
                            key={option}
                            type="button"
                            onClick={() => onYearChange(option)}
                            className={cn(
                                "rounded-medium px-2 py-0 text-xs",
                                option === year
                                    ? "bg-primary/15 text-primary"
                                    : "text-muted hover:text-foreground",
                            )}
                        >
                            {option}
                        </button>
                    ))}
                </div>
            </div>

            {/* draggable grid (Γëê53 columns can exceed the viewport): grab + pull
                horizontally instead of a native scrollbar. Framer constrains the
                motion track to the viewport box so it can't be flung off-edge. */}
            <div
                ref={viewportRef}
                className="cursor-grab overflow-hidden active:cursor-grabbing"
            >
                <motion.div
                    drag="x"
                    dragConstraints={viewportRef}
                    dragElastic={0.04}
                    dragMomentum={false}
                    className="flex w-max flex-col gap-2"
                >

                    {/* month labels aligned to the week columns */}
                    <div className="flex gap-[3px] pl-8">
                        {monthLabels.map((label, index) => (
                            <div
                                key={index}
                                className="w-3 shrink-0 whitespace-nowrap text-[10px] text-muted"
                            >
                                {label}
                            </div>
                        ))}
                    </div>

                    <div className="flex gap-[3px]">
                        {/* weekday labels (Mon/Wed/Fri) */}
                        <div className="flex w-8 shrink-0 flex-col gap-[3px] pr-1">
                            {Array.from({
                                length: 7,
                            }).map((_, dayIndex) => {
                                const weekday = weekdayLabels.find(
                                    (entry) => entry.dayIndex === dayIndex,
                                )
                                return (
                                    <div
                                        key={dayIndex}
                                        className="h-3 text-right text-[10px] leading-3 text-muted"
                                    >
                                        {weekday?.label ?? ""}
                                    </div>
                                )
                            })}
                        </div>

                        {/* one column per week */}
                        {weeks.map((column, columnIndex) => (
                            <div
                                key={columnIndex}
                                className="flex shrink-0 flex-col gap-[3px]"
                            >
                                {column.map((cell) => (
                                    <div
                                        key={cell.dateStr}
                                        onMouseEnter={cell.inYear
                                            ? (event) => {
                                                // anchor the shared popover above this cell
                                                const rect = event.currentTarget.getBoundingClientRect()
                                                setHovered({
                                                    cell,
                                                    x: rect.left + rect.width / 2,
                                                    y: rect.top,
                                                })
                                            }
                                            : undefined}
                                        onMouseLeave={cell.inYear
                                            ? () => setHovered(null)
                                            : undefined}
                                        className={cn(
                                            "h-3 w-3 shrink-0 rounded-sm",
                                            cell.inYear ? LEVEL_CLASS[levelOf(cell.total)] : "bg-transparent",
                                        )}
                                    />
                                ))}
                            </div>
                        ))}
                    </div>
                </motion.div>
            </div>

            {/* legend: Less ΓåÆ More */}
            <div className="flex items-center justify-end gap-2 text-[10px] text-muted">
                <span>{t("dashboard.contributions.less")}</span>
                {LEVEL_CLASS.map((levelClass, index) => (
                    <span
                        key={index}
                        className={cn("h-3 w-3 shrink-0 rounded-sm",
                            levelClass)}
                    />
                ))}
                <span>{t("dashboard.contributions.more")}</span>
            </div>

            {/* single shared popover, anchored above the hovered cell */}
            {hovered ? (
                <div
                    style={{
                        position: "fixed",
                        left: hovered.x,
                        top: hovered.y - 8,
                        transform: "translate(-50%, -100%)",
                    }}
                    className="pointer-events-none z-50 flex flex-col gap-0 rounded-medium border border-default bg-surface px-2 py-2 text-xs shadow-lg"
                >
                    <span className="font-medium text-foreground">
                        {new Date(`${hovered.cell.dateStr}T00:00:00Z`).toLocaleDateString(locale)}
                    </span>
                    <span className="text-foreground">
                        {t("dashboard.contributions.cellTitle",
                            {
                                count: hovered.cell.total,
                            })}
                    </span>
                    {hovered.cell.total > 0 ? (
                        <span className="text-muted">
                            {t("dashboard.contributions.breakdown",
                                {
                                    contents: hovered.cell.contents,
                                    challenges: hovered.cell.challenges,
                                    milestones: hovered.cell.milestones,
                                })}
                        </span>
                    ) : null}
                </div>
            ) : null}
        </div>
    )
}

"use client"

import React, {
    useCallback,
    useState,
} from "react"
import { toast } from "@/modules/toast/toast"
import { useTranslations } from "next-intl"
import type {
    CvSubmissionFormValues,
} from "@/types"
import { mutateGetCVPresignedUrl } from "@/modules/api/graphql/mutations/mutation-get-cv-presigned-url"
import { mutateProcessCV } from "@/modules/api/graphql/mutations/mutation-process-cv"
import { useAppSelector } from "@/redux/hooks"
import { CVSubmissionForm } from "@/components/blocks/careers/CVSubmissionForm"
import { useRestWithToast } from "@/modules/toast/hooks"

/** Fraction of progress shown after each upload step (UI feedback only). */
const UPLOAD_PROGRESS = {
    /** Presigned-URL request issued. */
    presign: 20,
    /** S3 PUT in flight. */
    uploading: 40,
    /** Upload finished. */
    done: 100,
} as const

/** Props for {@link CvSubmission}. */
export type CvSubmissionProps = Record<string, never>
/**
 * CV submission container.
 *
 * Owns the business logic ΓÇö auth token (redux), upload/process state, the
 * presigned-URL + S3 upload + process mutations ΓÇö and renders the presentational
 * {@link CVSubmissionForm}. `"use client"` because it holds state + side effects.
 * @param props - {@link CvSubmissionProps}
 */
export const CvSubmission = () => {
    /** Keycloak access token used to authorize the API calls. */
    const token = useAppSelector((state) => state.keycloak.accessToken)
    /** Whether the S3 upload step is in progress. */
    const [isUploading, setIsUploading] = useState(false)
    /** Whether the backend processing step is in progress. */
    const [isProcessing, setIsProcessing] = useState(false)
    /** Upload progress percentage (0ΓÇô100). */
    const [uploadProgress, setUploadProgress] = useState(0)
    /** Name of the successfully uploaded file, or `null`. */
    const [uploadedFileName, setUploadedFileName] = useState<string | null>(null)
    /** S3 key of the successfully uploaded file, or `null`. */
    const [uploadedS3Key, setUploadedS3Key] = useState<string | null>(null)
    /** Localized toast wrapper for REST calls. */
    const runRest = useRestWithToast()
    const t = useTranslations("cv.submission")

    /** Upload the selected CV to S3 via a presigned URL. */
    const onSubmit = useCallback(
        async (
            values: CvSubmissionFormValues,
        ) => {
            if (!token) {
                console.error("Authentication token not found")
                return
            }
            if (!values.cv) {
                console.error("CV file is required")
                return
            }

            try {
                setIsUploading(true)
                setUploadProgress(0)
                setUploadedFileName(null)
                setUploadedS3Key(null)

                // Step 1: get a presigned URL from the backend
                setUploadProgress(UPLOAD_PROGRESS.presign)
                const presignedUrlResponse = await mutateGetCVPresignedUrl({
                    request: {
                        fileName: values.cv.name,
                        fileType: values.cv.type,
                    },
                    token,
                })
                if (!presignedUrlResponse.data?.getCVPresignedUrl?.data) {
                    throw new Error(
                        presignedUrlResponse.data?.getCVPresignedUrl?.message
                            || "Failed to get presigned URL",
                    )
                }
                const {
                    url: presignedUrl,
                    key: s3Key,
                } = presignedUrlResponse.data.getCVPresignedUrl.data

                // Step 2: upload the file to S3 via PUT
                setUploadProgress(UPLOAD_PROGRESS.uploading)
                const cvFile = values.cv
                const uploadResponse = await runRest(
                    async () => {
                        const response = await fetch(presignedUrl, {
                            method: "PUT",
                            body: cvFile,
                            headers: {
                                "Content-Type": cvFile.type,
                            },
                        })
                        if (!response.ok) {
                            throw new Error(
                                `Failed to upload file to S3: ${response.statusText}`,
                            )
                        }
                        return response
                    },
                    {
                        showSuccessToast: false,
                    },
                )
                if (!uploadResponse) {
                    return
                }

                setUploadProgress(UPLOAD_PROGRESS.done)
                setUploadedFileName(values.cv.name)
                setUploadedS3Key(s3Key)
                // the form resets itself via a useEffect once these two props are set
            } catch (error) {
                console.error("CV upload error:", error)
                toast.danger(t("uploadError"))
            } finally {
                setIsUploading(false)
            }
        },
        [
            token,
            runRest,
            t,
        ],
    )

    /** Trigger backend processing of the previously uploaded CV. */
    const onProcess = useCallback(
        async () => {
            if (!token) {
                console.error("Authentication token not found")
                return
            }
            if (!uploadedS3Key || !uploadedFileName) {
                console.error("Please upload CV first")
                return
            }

            try {
                setIsProcessing(true)
                const processResponse = await mutateProcessCV({
                    request: {
                        s3Key: uploadedS3Key,
                        fileName: uploadedFileName,
                    },
                    token,
                })
                if (!processResponse.data?.processCV?.data) {
                    throw new Error(
                        processResponse.data?.processCV?.message
                            || "Failed to process CV",
                    )
                }
            } catch (error) {
                console.error("CV process error:", error)
                toast.danger(t("processError"))
            } finally {
                setIsProcessing(false)
            }
        },
        [
            token,
            uploadedS3Key,
            uploadedFileName,
            t,
        ],
    )

    // CVSubmissionForm already stamps block identity ΓÇö promote it to the root.
    return (
        <CVSubmissionForm
            isUploading={isUploading}
            isProcessing={isProcessing}
            uploadProgress={uploadProgress}
            uploadedFileName={uploadedFileName}
            uploadedS3Key={uploadedS3Key}
            onSubmit={onSubmit}
            onProcess={onProcess}
        />
    )
}

"use client"

import React from "react"
import {
    cn,
} from "@heroui/react"
import {
    MedalIcon,
} from "@phosphor-icons/react"
import {
    BadgeImage,
} from "@/components/blocks/identity/BadgeImage"
import { getRank } from "@/modules/utils/rank"

/** Props for {@link MascotBadge}. */
export interface MascotBadgeProps {
    /** MinIO object key of the mascot art (bare animal, no baked frame). */
    objectKey: string
    /** Accessible name of the mascot. */
    name: string
    /** Whether the viewer has earned the badge at all. */
    earned: boolean
    /** Highest tier reached (1ΓÇô4), or null; drives the ring colour via rank. */
    tierReached: number | null
    /** Outer diameter in px (default 64). */
    size?: number
}

/**
 * A mascot badge: the bare animal art framed by a circular ring whose colour
 * encodes the viewer's rank (grey ΓåÆ bronze ΓåÆ silver ΓåÆ gold). Locked badges show
 * the art greyed-out inside a dashed neutral ring. One image per animal ΓÇö only
 * the ring colour changes across ranks, so art never has to be redrawn per tier.
 *
 * @param props - {@link MascotBadgeProps}
 */
export const MascotBadge = ({
    objectKey,
    name,
    earned,
    tierReached,
    size = 64}: MascotBadgeProps) => {
    const {
        rank,
        ring,
    } = getRank(earned, tierReached)
    // ring thickness + inner art scale with the badge so it reads at any size.
    // the art fills the full content box (box-sizing: border-box ΓåÆ already minus
    // the border) so the ring sits FLUSH against the mascot ΓÇö no transparent gap.
    const ringWidth = Math.max(3, Math.round(size * 0.06))
    const innerSize = size - ringWidth * 2

    return (
        <div
            className={cn(// clip the (slightly over-scaled) art to the ring so the mascot
                // hugs the ring with no transparent gap from the PNG's own padding
                "flex shrink-0 items-center justify-center overflow-hidden rounded-full",
                !rank && "border-dashed border-default-300")}
            style={{
                width: size,
                height: size,
                // earned ΓåÆ solid metallic rank ring; locked ΓåÆ dashed neutral (class)
                ...(rank
                    ? { border: `${ringWidth}px solid ${ring}` }
                    : { borderWidth: ringWidth }),
            }}
        >
            <BadgeImage
                objectKey={objectKey}
                size={innerSize}
                alt={name}
                className={cn(
                    // scale up to eat the art's built-in transparent margin so the
                    // visible animal reaches the ring (overflow clipped by parent)
                    "rounded-full object-cover scale-[1.18]",
                    !earned && "opacity-40 grayscale",
                )}
                fallback={(
                    <MedalIcon
                        width={innerSize}
                        height={innerSize}
                        className={cn(earned ? "text-warning-soft-foreground" : "text-default-400")}
                    />
                )}
            />
        </div>
    )
}

