import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { FlameIcon, GithubLogoIcon, GlobeIcon, LinkedinLogoIcon, MapPinIcon } from "@phosphor-icons/react"
import { Tabs, type TabItem } from "@/components/atoms/navigation/Tabs"
import { Typography, type TypographyIcon } from "@/components/atoms/text/Typography"
import { Chip } from "@/components/atoms/chips/Chip"
import { Button } from "@/components/atoms/buttons/Button"
import { IconTile } from "@/components/atoms/display/IconTile"
import { AvatarGroup, type AvatarGroupItem } from "@/components/composites/lists/AvatarGroup"
import { InlineIconLabel } from "@/components/composites/text/InlineIconLabel"
import { ProgressBar } from "@/components/atoms/display/Progress"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Container } from "@/components/frames/Container"
import { Box } from "@/components/frames/Box"
import { StackV, StackH } from "@/components/frames/Stack"
import { Grid, type GridItem } from "@/components/frames/Grid"
import { RailShell } from "@/components/frames/RailShell"
import type { CallerIdentity } from "@/components/frames/_identity"

/**
 * BLOCK ΓÇö `ProfileLoadingState`: the public-profile first-load skeleton. It
 * takes no data props (see the component's own file header) so it has exactly
 * ONE leaf and ONE state ΓÇö there is no prop to vary it by.
 *
 * `annotate` (flat map, not a nested `parts` tree) is the right shape here for
 * the same reason `ContinueCard`'s own `Skeleton` leaf uses it: every text/pill/
 * progress/tile spot renders through an atom's OWN `isSkeleton` branch, so the
 * DOM this leaf produces really is flat repeats of a handful of part names
 * (`Typography`, `Chip`, `Button`, `IconTile`, `Avatar`, `Skeleton`ΓÇª), not a
 * meaningfully nested composition tree.
 *
 * The outer split (identity rail beside the overview column) is `RailShell` ΓÇö
 * the same leading-rail-beside-a-growing-body khung `SettingsLayout` composes
 * through, column-first on narrow screens and a row from `@app-md`.
 */

/** Props for {@link ProfileLoadingState}. Pure skeleton ΓÇö no data props (see file header). */
export interface ProfileLoadingStateProps {
    /**
 * Caller identity to wear on this block's root instead of its own ΓÇö pass this
 * when a `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape
 * of its own) is using this block AS its root element, instead of wrapping it in a
 * raw `<div data-tier=ΓÇª data-component=ΓÇª>`. See `_identity.ts`. Omitted -> this root
 * (a `StackV` track) keeps emitting its own underlying `data-tier="frame"
 * data-component="Flex"`, same as any other unbadged `StackV` instance.
 */
    identity?: CallerIdentity
}

/** Placeholder tab-strip items ΓÇö 5 tabs (overview/projects/challenges/skills/activity), never read: `Tabs isSkeleton` never renders a label. */
const TAB_ITEMS: Array<TabItem> = [0, 1, 2, 3, 4].map((i) => ({ key: `tab-${i}`, label: "" }))

/** Placeholder medal-strip members ΓÇö `AvatarGroup` needs `items` even while skeleton (its shimmer mirrors `items.length` slots). */
const MEDAL_ITEMS: Array<AvatarGroupItem> = [0, 1, 2, 3, 4].map((i) => ({ key: `medal-${i}` }))

/** One meta row's stable key + the icon its loaded counterpart would show ΓÇö github / linkedin / website, mirrors `ProfileHero`'s own `SOCIAL_META`. */
const META_ROWS: ReadonlyArray<{ key: string; icon: TypographyIcon }> = [
    { key: "meta-github", icon: GithubLogoIcon },
    { key: "meta-linkedin", icon: LinkedinLogoIcon },
    { key: "meta-website", icon: GlobeIcon },
]

/**
 * The public-profile first-load skeleton. See the file header for why the
 * section order is hard-coded and why two spots fall back to a raw HeroUI
 * `Skeleton` (documented `couldNotFix` gaps ΓÇö see the PR notes: a 128px avatar
 * and a heatmap-shaped rectangle have no matching atom to stand in for them).
 *
 * @param props - {@link ProfileLoadingStateProps}
 */
export const ProfileLoadingState = ({ identity }: ProfileLoadingStateProps) => {
    // Free-form rows built here (not by `SurfaceCardList`'s own `isSkeleton`, ┬º12c):
    // the courses/readiness rows carry BESPOKE content (an IconTile, a progress
    // bar), not the composite's fixed leading/title/subtitle slots, so each row
    // passes `content` and stays untouched by the list's own shimmer branch.
    const readinessTrack = (
        <>
            <Typography size="sm" isSkeleton />
            <ProgressBar isSkeleton />
            <ProgressBar isSkeleton />
        </>
    )

    const readinessItems: Array<SurfaceCardListItem> = [
        {
            key: "readiness-track",
            content: () => <StackV gap={4} items={[() => readinessTrack]} />,
        },
    ]

    const courseItems: Array<SurfaceCardListItem> = [0, 1].map((i) => {
        const progressHeader = (
            <>
                <Typography size="sm" isSkeleton />
                <Typography size="xs" isSkeleton classNames={["w-1/4", "shrink-0"]} />
            </>
        )
        const courseDetails = (
            <>
                <StackH gap={3} principle="value-row"
                    explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                    justify="between" items={[() => progressHeader]}  />
                <ProgressBar isSkeleton />
            </>
        )
        const courseRow = (
            <>
                <IconTile isSkeleton size="sm" />
                <StackV gap={3} classNames={["min-w-0", "flex-1"]} items={[() => courseDetails]} />
            </>
        )
        return {
            key: `course-${i}`,
            content: () => <StackH gap={4} items={[() => courseRow]} />,
        }
    })

    const skillItems: Array<GridItem> = [0, 1].map((i) => {
        const statCardBody = (
            <>
                <Typography size="h3" isSkeleton classNames={["w-1/4"]} />
                <Typography size="sm" isSkeleton classNames={["w-2/3"]} />
                <Typography size="xs" isSkeleton classNames={["w-1/3"]} />
            </>
        )
        const skillCard = (
            <>
                <Typography size="h4" isSkeleton />
                <SurfaceCard
                    padding={4}
                    body={() => <StackV gap={3} items={[() => statCardBody]} />}
                />
            </>
        )
        return {
            key: `skill-${i}`,
            content: () => <StackV gap={4} items={[() => skillCard]} />,
        }
    })

    // ΓöÇΓöÇ identity column ΓÇö bare, no card face (matches `ProfileHeroSkeleton`) ΓöÇΓöÇ

    // rank-framed avatar + rank pill ΓÇö 128px avatar has no matching `Avatar`
    // preset (sm/md/lg cap at 48px), so this spot builds its own shimmer.
    // WARNING∩╕Å couldNotFix (no-heroui-outside-vocabulary): no atom offers a 128px
    // circular shimmer, so this stays a raw HeroUI `Skeleton`.
    const rankAvatarRow = (
        <>
            <Skeleton className="size-32 rounded-full" />
            <Chip isSkeleton />
        </>
    )

    // name (h3) + role title + @handle ΓÇö one unit of meaning, flush
    const nameBlock = (
        <>
            <Typography size="h3" isSkeleton classNames={["w-3/4"]} />
            <Typography size="sm" isSkeleton />
            <Typography size="sm" isSkeleton classNames={["w-1/3"]} />
        </>
    )

    // location ┬╖ preferred work mode ΓÇö `InlineIconLabel` is the sanctioned
    // "leading icon + inline text" composite (mirrors `ProfileHero`'s own use
    // of it for this exact row).
    const locationRow = (
        <>
            <InlineIconLabel icon={MapPinIcon} isSkeleton size="sm" skeletonWidth="w-1/3" />
            <Chip isSkeleton />
        </>
    )

    // follower / following line
    const followRow = (
        <>
            <Typography size="sm" isSkeleton classNames={["w-1/3"]} />
            <Typography size="sm" isSkeleton classNames={["w-1/3"]} />
        </>
    )

    // action cluster ΓÇö two full-width buttons
    const actionButtons = (
        <>
            <Button isSkeleton classNames={["w-full"]} />
            <Button isSkeleton classNames={["w-full"]} />
        </>
    )

    // meta: github ┬╖ linkedin ┬╖ website ΓÇö leading icon + text rows, each one `InlineIconLabel`.
    const metaRows = META_ROWS.map((row) => (
        <InlineIconLabel key={row.key} icon={row.icon} isSkeleton size="sm" skeletonWidth="w-1/2" />
    ))

    const identityColumnBody = (
        <>
            <StackV gap={2} principle="title-subtitle"
                explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                align="start" items={[() => rankAvatarRow]}  />
            <StackV gap={1} items={[() => nameBlock]} />

            {/* short bio */}
            <Typography size="sm" isSkeleton classNames={["w-2/3"]} />

            <StackH gap={3} principle="chip-row"
                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                at="sm" items={[() => locationRow]}  />
            <StackH gap={4} items={[() => followRow]} />

            {/* earned-badge medal strip ΓÇö `AvatarGroup` already owns the overlap look */}
            <AvatarGroup items={MEDAL_ITEMS} size="sm" isSkeleton />

            <StackV gap={3} items={[() => actionButtons]} />
            <StackV gap={4} items={[() => metaRows]} />
        </>
    )

    // ΓöÇΓöÇ overview body ΓÇö the four sections, in the real screen's own order ΓöÇΓöÇ

    const readinessCard = (
        <>
            <Typography size="h3" isSkeleton classNames={["w-1/4"]} />
            <Typography size="sm" isSkeleton classNames={["w-2/3"]} />
            <Typography size="xs" isSkeleton classNames={["w-1/3"]} />
        </>
    )
    const readinessGroup = (
        <>
            <SurfaceCard
                padding={4}
                body={() => <StackV gap={3} items={[() => readinessCard]} />}
            />
            <SurfaceCardList
                items={readinessItems}
            />
        </>
    )
    // job readiness ΓÇö headline metric card + a tracked-goal row
    const readinessSection = (
        <>
            <Typography size="h4" isSkeleton />
            <StackV gap={4} items={[() => readinessGroup]} />
        </>
    )

    // courses ΓÇö icon tile + title/percent + progress rows
    const coursesSection = (
        <>
            <Typography size="h4" isSkeleton />
            <SurfaceCardList
                items={courseItems}
            />
        </>
    )

    // contributions ΓÇö heatmap grid + streak line
    // WARNING∩╕Å couldNotFix (no-heroui-outside-vocabulary): no atom offers an
    // arbitrary-sized rounded rectangle shimmer, so the heatmap placeholder
    // stays a raw HeroUI `Skeleton`.
    const contributionGroup = (
        <>
            <Skeleton className="h-40 w-full rounded-xl" />
            <InlineIconLabel icon={FlameIcon} isSkeleton size="sm" skeletonWidth="w-1/2" />
        </>
    )
    const contributionsSection = (
        <>
            <Typography size="h4" isSkeleton />
            <StackV gap={4} items={[() => contributionGroup]} />
        </>
    )

    const overviewSections = (
        <>
            <StackV gap={4} items={[() => readinessSection]} />
            <StackV gap={4} items={[() => coursesSection]} />
            <StackV gap={4} items={[() => contributionsSection]} />
            {/* skills ΓÇö 2-col grid of stat cards */}
            <Grid columns={{ base: 1, md: 2 }} principle="block-boundary"
                explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                items={skillItems}  />
        </>
    )

    // outer split: identity rail first (mobile), row from `@app-md` ΓÇö `RailShell`,
    // the same leading-rail-beside-a-growing-body khung `SettingsLayout` composes
    // through instead of a hand-rolled `StackV` + breakpoint className (that raw
    // shape is exactly what `no-raw-shape-at-sentence-tier` forbids here).
    const identityRail: ComponentTypeWithSkeleton = () => (
        <StackV gap={4} items={[() => identityColumnBody]} />
    )

    const overviewContent: ComponentTypeWithSkeleton = () => (
        <StackV gap={6} items={[() => overviewSections]} />
    )

    const overviewBody = <RailShell principle="layout-split"
        explain="Major layout split ΓÇö not block-boundary, because this separates primary page regions rather than adjacent blocks."
        rail={identityRail} body={overviewContent} at="md"  />

    return (
        // WARNING∩╕Å couldNotFix (require-identity-root / no-raw-shape-at-sentence-tier):
        // the previous root also carried `aria-busy="true"` and
        // `aria-label="Loading profile"` on a raw `<div>`. No frame in
        // `components/frames/` forwards arbitrary ARIA attributes (`Flex`/`Stack`/
        // `Box` all destructure a closed prop list with no `...rest` passthrough),
        // so moving the root onto `StackV` drops those two attributes ΓÇö flagged
        // rather than silently lost; adding `aria-*` passthrough to `Flex` is out
        // of this file's scope.
        // gap={1} (0px) between tabs and body was intentional no-seam ΓÇö a StackV
        // frame was redundant; Box carries identity only.
        <Box
            className="w-full"
            identity={identity}
        >
            {/* tab strip ΓÇö full-bleed row under the navbar, same footprint as `ProfileTabsBar`.
 `px-6 py-3` is a one-off placement wrapper (a full-width strip flush under a sticky
 navbar, not a repeating list nor a generic card seam), same allowance `ContinueCard`
 uses for its own content wrapper ΓÇö both padding digits (6, 3) are on the ┬º10c scale.
 Carried via `Container`'s own `padding` prop (house-scale {{ x: 6, y: 4 }} = `px-6 py-3`)
 instead of a raw div ΓÇö no `patterns.mjs` token names this asymmetric shape yet. */}
            <Container
                size="full"
                padding={{ x: 6, y: 4 }}
                body={() => (
                    <Tabs
                        items={TAB_ITEMS}
                        selectedKey={TAB_ITEMS[0].key}
                        onSelectionChange={() => {}}
                        ariaLabel="Profile sections loading"
                        variant="secondary"
                        isSkeleton
                    />
                )}
            />
            <Container size="lg" padding={6} body={() => overviewBody} />
        </Box>
    )
}

"use client"

import React, { useCallback, useMemo } from "react"
import { Tabs } from "@heroui/react"
import {
    HouseIcon,
    PuzzlePieceIcon,
    RocketIcon,
    CodeIcon,
    FileTextIcon,
    PulseIcon,
} from "@phosphor-icons/react"
import { useTranslations, useLocale } from "next-intl"
import { usePathname, useRouter } from "next/navigation"
import type { SectionVisibility } from "@/modules/types/entities/user"
import { PROFILE_TABS } from "@/modules/types/entities/profile"
import type { ProfileTab } from "@/modules/types/entities/profile"
import { ExtendedTabs } from "@/components/blocks/navigation/ExtendedTabs"
import { pathConfig } from "@/resources/path"

/**
 * The section tabs gated by `sectionVisibility` (Overview + CV are never gated ΓÇö
 * Overview always shows, CV keeps its own `hasPublicCv` gate).
 */
const SECTION_TABS: ReadonlyArray<keyof SectionVisibility> = [
    "projects",
    "challenges",
    "skills",
    "activity",
]

/** Whether a tab is one of the visibility-gated section tabs. */
const isSectionTab = (tabId: ProfileTab): tabId is keyof SectionVisibility =>
    (SECTION_TABS as ReadonlyArray<ProfileTab>).includes(tabId)

/** Leading icon shown on each profile tab, keyed by tab id. */
const TAB_ICONS: Record<ProfileTab, typeof HouseIcon> = {
    overview: HouseIcon,
    challenges: PuzzlePieceIcon,
    projects: RocketIcon,
    skills: CodeIcon,
    cv: FileTextIcon,
    activity: PulseIcon,
}

/** Props for {@link ProfileTabsBar}. */
export interface ProfileTabsBarProps {
    /** The viewed user's canonical username (drives every tab's href). */
    username: string
    /** Whether the viewer is the profile owner ΓÇö shows the "CV" tab even without a public CV. */
    isSelf: boolean
    /** Whether the viewed user has a PUBLIC CV ΓÇö shows the "CV" tab to visitors too. */
    hasPublicCv: boolean
    /**
     * The viewed user's per-section visibility (all default true). A section tab is
     * withheld from VISITORS when its flag is false; the owner ({@link isSelf}) always
     * sees every tab (with a "┬╖ hidden" marker on hidden ones). Absent = all visible.
     */
    sectionVisibility?: SectionVisibility
}

/**
 * Build the href for a profile tab. Every tab nests under `/profile/<username>`,
 * INCLUDING "cv" ΓÇö the public, read-only CV view (`/profile/<username>/cv`). The
 * owner's private editor stays reachable from the "Edit CV" button inside
 * that view (the always-own `/profile/cv` gallery).
 */
const tabHref = (locale: string, username: string, tabId: ProfileTab): string => {
    const profile = pathConfig().locale(locale).profile(username)
    switch (tabId) {
    case "overview":
        return profile.overview().build()
    case "projects":
        return profile.projects().build()
    case "challenges":
        return profile.challenges().build()
    case "skills":
        return profile.skills().build()
    case "activity":
        return profile.activity().build()
    case "cv":
        return profile.cv().build()
    }
}

/**
 * Full-width tab strip for the profile page. The page registers it as the global
 * Navbar's bottom layer ({@link useRegisterNavbarBottomLayer}); the Navbar renders
 * it flush under its primary row and owns the single bottom border + sticky, so
 * this strip carries no border / sticky / bg of its own. Uses the native HeroUI
 * secondary Tabs (foreground text on the selected tab + an accent underline
 * indicator).
 *
 * Each tab is a real nested route (`/profile/<username>/<tab>`, bare = overview) ΓÇö
 * the active tab is derived from the URL pathname and switching a tab
 * `router.push`es its href, mirroring the `pathname === href` + `router.push`
 * pattern `SettingsLayout` already uses for its own route-derived nav. No store,
 * no `?tab=` query param: the URL alone is the source of truth, so the open tab
 * is shareable / bookmarkable / back-forward friendly for free.
 *
 * @param props - {@link ProfileTabsBarProps}
 */
export const ProfileTabsBar = ({ username, isSelf, hasPublicCv, sectionVisibility}: ProfileTabsBarProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const pathname = usePathname()
    // Whether a SECTION tab is hidden for the current viewer: false flag + visitor.
    // The owner (isSelf) always sees it (just marked "┬╖ hidden"); an absent flag = visible.
    const isSectionHidden = useCallback(
        (tabId: ProfileTab): boolean =>
            !isSelf && isSectionTab(tabId) && sectionVisibility?.[tabId] === false,
        [isSelf, sectionVisibility],
    )
    // Tab gating, combined:
    //  ΓÇó "cv" shows for the owner (always) or when the viewed user has a PUBLIC CV.
    //  ΓÇó a section tab (projects/challenges/skills/activity) is withheld from VISITORS
    //    when its sectionVisibility flag is false. Overview is never gated.
    const visibleTabs = useMemo(
        () => PROFILE_TABS.filter((tabId) => {
            if (tabId === "cv") {
                return isSelf || hasPublicCv
            }
            return !isSectionHidden(tabId)
        }),
        [isSelf, hasPublicCv, isSectionHidden],
    )

    // active tab = the tab whose path is a PREFIX of the current pathname (so a
    // nested sub-route like `/challenges/<courseId>/<id>` still lights up its tab).
    // "overview" is the bare `/profile/<username>` path ΓÇö a prefix of everything ΓÇö
    // so it's only the FALLBACK when no deeper tab matches.
    const activeTab = useMemo<ProfileTab>(() => {
        const match = visibleTabs
            .filter((tabId) => tabId !== "overview")
            .find((tabId) => {
                const href = tabHref(locale, username, tabId)
                return pathname === href || pathname.startsWith(`${href}/`)
            })
        return match ?? "overview"
    }, [visibleTabs, pathname, locale, username])

    return (
        // Rendered as the Navbar's bottom layer ΓÇö no border / sticky / bg of its
        // own; the Navbar root owns the single bottom border and the sticky.
        <div className={"w-full"}>
            <div className="w-full px-6">
                <ExtendedTabs
                    selectedKey={activeTab}
                    onSelectionChange={(key) => router.push(tabHref(locale, username, key as ProfileTab))}
                >
                    <Tabs.ListContainer>
                        <Tabs.List aria-label={t("publicProfile.title")}>
                            {visibleTabs.map((tabId) => {
                                const TabIcon = TAB_ICONS[tabId]
                                return (
                                    <Tabs.Tab
                                        key={tabId}
                                        id={tabId}
                                        aria-controls={`profile-panel-${tabId}`}
                                    >
                                        <span className="flex items-center gap-2">
                                            <TabIcon
                                                aria-hidden
                                                focusable="false"
                                                className="size-5 shrink-0"
                                            />
                                            {/* mobile = icon only; label shows from md up */}
                                            <span className="hidden @app-md:inline">
                                                {t(`publicProfile.tabs.${tabId}`)}
                                                {/* owner-only marker on a section hidden from
                                                    visitors (visitors never see the tab at all) */}
                                                {isSelf && isSectionTab(tabId) && sectionVisibility?.[tabId] === false ? (
                                                    <span className="ml-1 text-foreground-500">
                                                        {t("publicProfile.tabHidden")}
                                                    </span>
                                                ) : null}
                                            </span>
                                        </span>
                                        <Tabs.Indicator />
                                    </Tabs.Tab>
                                )
                            })}
                        </Tabs.List>
                    </Tabs.ListContainer>
                </ExtendedTabs>
            </div>
        </div>
    )
}

"use client"

import React from "react"
/** Props for {@link RankBadge}. */
export interface RankBadgeProps {
    /** Display label for the rank (already localised, e.g. "Senior"). */
    label: string
    /** Hex colour encoding the rank tier (grey ΓåÆ bronze ΓåÆ silver ΓåÆ gold). */
    color: string
}

/**
 * Seniority rank pill ΓÇö a coloured dot + the rank label (Beginner ΓåÆ Senior),
 * tinted by the rank's tier colour. Presentational: the caller resolves the
 * user's rank ΓåÆ `{ label, color }` (e.g. via `getRank`) and passes it in.
 *
 * NO border: a soft 10%-tint fill of the rank colour with the dot + label in the
 * full colour (a chip is one colour family, not an outline). `color` is a runtime
 * hex, so the fill uses `color-mix(... 10%, transparent)` (format-agnostic) ΓÇö the
 * inline-style equivalent of `bg-[color]/10`.
 *
 * @param props - {@link RankBadgeProps}
 */
export const RankBadge = ({
    label,
    color}: RankBadgeProps) => {
    return (
        <span
            className={"inline-flex w-fit items-center gap-2 rounded-full px-2 py-0 text-xs font-medium"}
            style={{
                backgroundColor: `color-mix(in srgb, ${color} 10%, transparent)`,
                color,
            }}
        >
            <span
                className="size-2 rounded-full"
                style={{
                    backgroundColor: color,
                }}
            />
            {label}
        </span>
    )
}

"use client"

import React from "react"
import {
    CaretUpIcon,
    CaretDownIcon,
} from "@phosphor-icons/react"
import {
    cn,
} from "@heroui/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"

/** Props for {@link RankDeltaCaret}. */
export interface RankDeltaCaretProps extends WithClassNames<undefined> {
    /**
     * Rank movement vs the previous period (`lastRank - currentRank`): positive
     * = climbed N places (Γû▓ green), negative = dropped (Γû╝ red), 0 = unchanged
     * (muted dash), null = no baseline (renders nothing).
     */
    delta: number | null
}

/**
 * The rank-movement caret shown at the end of a leaderboard row: a green up
 * arrow + count when the user climbed, a red down arrow + count when they
 * dropped, a muted dash when unchanged, and nothing when there's no baseline.
 * Reused by the weekly-league board + the global leaderboard.
 *
 * @param props - {@link RankDeltaCaretProps}
 */
export const RankDeltaCaret = ({
    delta,
    className,
}: RankDeltaCaretProps) => {
    // no last-period baseline ΓåÆ an EMPTY SPACER that still reserves the column width
    // (the caller's `className` carries the `w-8`), so a #1 row with no movement keeps
    // the value/delta columns aligned with the rows below it instead of letting the
    // value slide right into the empty slot (the teacher, 2026-07-17: "the green ones need to line up").
    if (delta === null) {
        return <span className={cn(className)} aria-hidden />
    }
    // unchanged ΓåÆ a muted dash so the column still aligns
    if (delta === 0) {
        return (
            <span className={cn("text-xs text-muted", className)}>
                ΓÇö
            </span>
        )
    }
    const climbed = delta > 0
    return (
        <span
            className={cn(
                "flex items-center gap-0 text-xs font-medium",
                climbed ? "text-success-soft-foreground" : "text-danger-soft-foreground",
                className,
            )}
        >
            {climbed ? (
                <CaretUpIcon className="size-3.5" />
            ) : (
                <CaretDownIcon className="size-3.5" />
            )}
            {Math.abs(delta)}
        </span>
    )
}

"use client"

import React from "react"
import { CourseCard } from "@/components/blocks/cards/CourseCard"
import { AddToCartButton } from "@/components/blocks/commerce/AddToCartButton"
import { Box } from "@/components/frames/Box"
import { useQueryCoursePricePreviewSwr } from "@/hooks/swr/api/graphql/queries/useQueryCoursePricePreviewSwr"
import type { CourseEntity } from "@/modules/types/entities/course"

/** Props for {@link CatalogCourseCard}. */
export interface CatalogCourseCardProps {
    /** The catalog course to render. */
    course: CourseEntity
    /** Card layout ΓÇö roomy `"grid"` (default) or compact `"line"` row. */
    layout?: "grid" | "line"
}

/**
 * Feature wrapper that enriches a catalog {@link CourseCard} with the viewer's
 * loyalty-discounted price so the catalog shows the SAME personalised price as the
 * rest of the app. Fetches `coursePricePreview` per course (disabled for guests, who
 * then see the phase price). Keeps {@link CourseCard} a pure presentational block.
 *
 * @param props - {@link CatalogCourseCardProps}
 */
export const CatalogCourseCard = ({ course, layout = "grid" }: CatalogCourseCardProps) => {
    const { data, isLoading } = useQueryCoursePricePreviewSwr(course.id)
    return (
        <CourseCard
            course={course}
            loyaltyPriceVnd={data?.discountedPriceVnd ?? null}
            loyaltyOriginalVnd={data?.originalPriceVnd ?? null}
            // 2026-07-12: without this, every card briefly shows the phase price
            // then silently swaps to the loyalty price once the preview lands ΓÇö
            // N simultaneous jumps across the catalog grid.
            loyaltyPending={isLoading && !data}
            layout={layout}
            // no `iconOnly` ΓÇö the view CTA is now a real primary Button (not a
            // subtle Link), so this secondary cart action gets a label+icon
            // too instead of reading as a stray icon (starci-fe-block-variants
            // round-2 direction "C"). `flex-1` so it splits the action row
            // evenly with the primary "view/continue" button ΓÇö without it the
            // row was uneven card-to-card (button width = own content only,
            // not the row's real available width).
            action={() => (
                <Box className="flex-1">
                    <AddToCartButton
                        course={course}
                        isEnrolled={course.isEnrolled ?? undefined}
                        variant="secondary"
                    />
                </Box>
            )}
        />
    )
}

"use client"

import React from "react"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Loading placeholder for ONE compact "line" catalog row ΓÇö mirrors
 * {@link import("../CatalogCourseCard").CatalogCourseCard}'s `layout="line"` shape
 * (thumbnail, title + one description line, a price line, and a two-button
 * action row) so the catalog's line view does not jump when data resolves.
 *
 * `CatalogCourseCard` has no `isSkeleton` prop of its own (it wraps the
 * `CourseCard` block, neither of which is in scope for this split), so this is
 * the minimal co-located mirror the loading-and-skeleton.md escape hatch calls
 * for ΓÇö kept right beside the row it stands in for, not a separate top-level
 * skeleton tree swapped in wholesale.
 */
export const CatalogLineCardSkeleton = () => (
    <SurfaceCard
        identity={{ tier: "block", component: "CatalogLineCardSkeleton" }}
        body={() => (
            <StackH
