/** Props for {@link _JobListPage} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface JobListPageProps {
    /** First load, nothing in hand ΓåÆ the row list shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero matching postings ΓåÆ the empty branch. */
    isEmpty?: boolean
    /** Truthy ΓåÆ the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retries the failed fetch. */
    onRetry?: () => void
    /** The current page of postings, already resolved. */
