    /** Clears search + every facet ΓÇö the filtered-empty branch's retry action. */
    onClearFilters?: () => void
    /** Opens the "post a job" flow ΓÇö the header CTA AND the platform-empty branch's action. */
    onPostJob: () => void

    /** Current search query (controlled). */
    search: string
    /** Fired with the new query on every keystroke. */
    onSearchChange: (value: string) => void
    /** Currently selected work-mode facet. */
    workModeFilter: WorkModeFilterValue
    onWorkModeFilterChange: (value: WorkModeFilterValue) => void
    /** Work-mode facet options, already localized. */
    workModeItems: Array<FlexWrapButtonRadioItem<WorkModeFilterValue>>
    /** Currently selected employment-type facet. */
    employmentTypeFilter: EmploymentTypeFilterValue
    onEmploymentTypeFilterChange: (value: EmploymentTypeFilterValue) => void
    /** Employment-type facet options, already localized. */
    employmentTypeItems: Array<FlexWrapButtonRadioItem<EmploymentTypeFilterValue>>
    /** Facets currently applied (0ΓÇô2) ΓÇö badges the filter trigger. */
    activeFacetCount: number
    /** Resets both facet rows without touching the search box. */
    onClearFacets: () => void

    /** 1-based current page. */
    page: number
    totalPages: number
    onPageChange: (page: number) => void

    labels: JobListLabels
}

/**
 * Loading placeholder for one job-posting row ΓÇö mirrors {@link JobListRow}'s
 * IconTile + title/company/meta + salary/time shape so the list does not
 * collapse or jump when data resolves. Co-located right here (not a separate
 * hand-kept file) since `JobListRow` takes no `isSkeleton` prop of its own to
 * thread through (`loading-and-skeleton.md`).
 */
const JobListRowSkeleton = () => (
    <SurfaceListCardItem>
        <StackH
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="center"
            items={[
                () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                () => (
                    <StackV
                        gap={2}
                        principle="title-subtitle"
                        explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                        classNames={["min-w-0", "flex-1"]}
                        items={[
                            () => <Skeleton.Typography type="body-sm" width="1/2" />,
                            () => <Skeleton.Typography type="body-xs" width="1/3" />,
                            () => (
                                <Cluster
                                    gap={3}
                                    principle="chip-row"
                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                    items={[
                                        () => <Skeleton.Typography type="body-xs" width="1/4" />,
                                        () => <Skeleton.Chip />,
                                    ]}
                                />
                            ),
                        ]}
                    />
                ),
                () => (
                    <StackV
                        gap={2}
                        principle="title-subtitle"
                        explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                        align="end"
                        classNames={["shrink-0"]}
                        items={[
                            () => <Skeleton.Typography type="body-sm" width="full" className="w-16" />,
                            () => <Skeleton.Typography type="body-xs" width="full" className="w-12" />,
                        ]}
                    />
                ),
            ]}
        />
    </SurfaceListCardItem>
)

/**
 * The job board (`/jobs`) ΓÇö the presentational half of {@link import("./index").JobListPage}. Search +
 * two single-select filter rows (work mode, employment type) behind a funnel popover drive a
 * paginated ROW LIST (not a card grid ΓÇö a posting has too many attributes ΓÇö title, company,
 * location, work mode, salary ΓÇö to read comfortably in a tile; every real job board renders rows).
 * Public ΓÇö works for anonymous viewers.
 *
 * The header + search/filter toolbar always render; only the row-list region below switches
 * error ΓåÆ (settled) empty ΓåÆ content, with `isSkeleton` threaded to every leaf that can mirror
 * itself (`loading-and-skeleton.md`). `JobListRow` (a sibling component owned outside this pass)
 * takes no `isSkeleton` prop, so the loading branch mirrors it minimally with the co-located
 * `JobListRowSkeleton` at the SAME position and the SAME row count ΓÇö not a parallel tree.
 *
 * Two distinct empty states (per the brainstorm's cold-start marketplace note): a filtered search
 * with zero matches offers a "clear filters" affordance, while a genuinely empty board (no postings
 * at all, yet) becomes a two-sided funnel ΓÇö "no listings yet ΓÇö is your company hiring? post one
 * free" ΓÇö instead of a dead end.
 *
 * @param props - {@link JobListPageProps}
 */
export const _JobListPage = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    items = [],
    isPlatformEmpty = false,
    onClearFilters,
    onPostJob,
    search,
    onSearchChange,
    workModeFilter,
    onWorkModeFilterChange,
    workModeItems,
    employmentTypeFilter,
    onEmploymentTypeFilterChange,
    employmentTypeItems,
    activeFacetCount,
    onClearFacets,
    page,
    totalPages,
    onPageChange,
    labels,
}: JobListPageProps) => {
    // funnel popover open state ΓÇö purely visual, needs no server/store/session (split.md's own test)
    const [filterOpen, setFilterOpen] = useState(false)

    const emptyPlatformAction: ComponentTypeWithSkeleton = () => (
        <Button variant="tertiary" size="sm" label={labels.emptyPlatformCta} onPress={onPostJob} />
    )

    const filterPopoverContent = (
        <StackV gap={3} items={[
            () => (
                <StackV gap={2} items={[
                    () => <Typography size="xs" color="muted" text={labels.workModeHeading} />,
                    () => (
                        <FlexWrapButtonRadio<WorkModeFilterValue>
                            ariaLabel={labels.workModeAria}
                            value={workModeFilter}
                            onChange={onWorkModeFilterChange}
                            items={workModeItems}
                        />
                    ),
                ]} />
            ),
            () => (
                <StackV gap={2} items={[
                    () => <Typography size="xs" color="muted" text={labels.employmentTypeHeading} />,
                    () => (
                        <FlexWrapButtonRadio<EmploymentTypeFilterValue>
                            ariaLabel={labels.employmentTypeAria}
                            value={employmentTypeFilter}
                            onChange={onEmploymentTypeFilterChange}
                            items={employmentTypeItems}
                        />
                    ),
                ]} />
            ),
            ...(activeFacetCount > 0 ? [() => (
                <Button variant="danger-soft" size="sm" label={labels.clearFacets} onPress={onClearFacets} classNames={["self-start"]} />
            )] : []),
        ]} />
    )

    // toolbar: search + funnel popover on the left, the resolved count on the right ΓÇö
    // always rendered, unaffected by the row-list region's own error/empty/content switch
    const toolbar = (
        <StackH gap={3} principle="flex-action" justify="between" align="center" at="sm"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            items={[
                () => (
                    <StackH gap={3} principle="flex-action" align="center" classNames={["min-w-0", "flex-1"]}
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        items={[
                            () => (
                                <SearchInput
                                    className="min-w-0 flex-1"
                                    value={search}
                                    onValueChange={onSearchChange}
                                    placeholder={labels.searchPlaceholder}
                                />
                            ),
                            () => (
                                <Badge count={activeFacetCount} color="accent" size="sm" placement="top-left">
                                    <Popover
                                        triggerLabel={<span className="sr-only">{labels.filterButtonAria}</span>}
                                        triggerIcon={FunnelIcon}
                                        triggerVariant="ghost"
                                        isOpen={filterOpen}
                                        onOpenChange={setFilterOpen}
                                        classNames={["shrink-0"]}
                                        content={filterPopoverContent}
                                    />
                                </Badge>
                            ),
                        ]} />
                ),
                () => <Typography size="sm" color="muted" classNames={["shrink-0"]} text={labels.found} />,
            ]} />
    )

    // row-list region ΓÇö the ONLY part of this block that switches state; the header +
    // toolbar above always render regardless of error/loading/empty/content.
    let listRegion: ReactNode
    if (error) {
        listRegion = <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    } else if (!isSkeleton && isEmpty) {
        listRegion = isPlatformEmpty ? (
            <AsyncContentEmpty
                icon={BriefcaseIcon}
                title={labels.emptyPlatformTitle}
                description={labels.emptyPlatformDescription}
                action={emptyPlatformAction}
            />
        ) : (
            <AsyncContentEmpty
                icon={TrayIcon}
                title={labels.emptyFilteredTitle}
                onRetry={onClearFilters}
                retryLabel={labels.emptyFilteredClearFilters}
            />
        )
    } else {
        // rows ΓÇö while shimmering, the SAME position holds SKELETON_ROW_COUNT placeholder
        // rows (JobListRow takes no isSkeleton prop, so the mirror is JobListRowSkeleton,
        // co-located here rather than a separate branch ΓÇö see missingSkeletonSupport).
        listRegion = (
            <StackV gap={3} items={[
                () => (
                    <SurfaceListCard>
                        {isSkeleton
                            ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => (
                                <JobListRowSkeleton key={index} />
                            ))
                            : items.map((job) => <JobListRow key={job.id} job={job} />)}
                    </SurfaceListCard>
                ),
                // pager: left-aligned with the rows, hidden on a single page
                ...(totalPages > 1 ? [() => (
                    <Pagination
                        className="mt-0 justify-start"
                        currentPage={page}
                        totalPages={totalPages}
                        onPageChange={onPageChange}
                    />
                )] : []),
            ]} />
        )
    }

    const jobListBody = (
        <StackV gap={8} items={[
            () => (
                <PageHeader
                    title={labels.pageTitle}
                    description={labels.pageDescription}
                    actions={<Button variant="secondary" label={labels.postCta} onPress={onPostJob} />}
                />
            ),
            () => toolbar,
            () => listRegion,
        ]} />
    )

    return (
        <Container
            size="md"
            padding={6}
            body={() => jobListBody}
            identity={{ tier: "block", component: "JobListPage" }}
        />
    )
}

"use client"

import React, {
    useMemo,
    useState,
} from "react"
import {
    Badge,
    Button,
    Popover,
    Typography,
    cn,
} from "@heroui/react"
import {
    FunnelIcon,
} from "@phosphor-icons/react"
import {
    useParams,
    useRouter,
} from "next/navigation"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import {
    difficultyLevel,
} from "@/modules/utils/challenge-difficulty"
import { pathConfig } from "@/resources/path"
import { dayjs } from "@/modules/dayjs"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserSolvedChallengesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserSolvedChallengesSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { DifficultyChip } from "@/components/blocks/chips/DifficultyChip"
import { LanguageChip } from "@/components/blocks/chips/LanguageChip"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { SearchInput } from "@/components/blocks/form/SearchInput"
import { FlexWrapButtonRadio } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/** Single-select difficulty filter value ΓÇö `"all"` clears the filter. */
type DifficultyFilterValue = "all" | string
/** Single-select language filter value ΓÇö `"all"` clears the filter. */
type LanguageFilterValue = "all" | string
/** Sort order for the submission list. */
type SortValue = "newest" | "score"

/**
 * Score ΓåÆ attention colour the eye catches fast: high green, mid yellow, low red.
 * @param score - the graded score (0ΓÇô100).
 * @returns a `text-{token}` class for the score label.
 */
const scoreToneClass = (score: number): string => {
    if (score >= 90) {
        return "text-success-soft-foreground"
    }
    if (score >= 70) {
        return "text-warning-soft-foreground"
    }
    return "text-danger-soft-foreground"
}

/** Props for {@link ProfileChallengeManagePage}. */
export type ProfileChallengeManagePageProps = Record<string, never>
/**
 * `/profile/<u>/challenges/<courseSlug>` ΓÇö the MANAGE tier of the 3-tier
 * challenges flow: search ONE course's passed-challenge submissions, with sort
 * (newest / highest score) and the difficulty/language facets tucked behind a
 * single FUNNEL popover next to the search box (keeps the toolbar one clean line).
 * Reads the course SLUG from the route, filters the profile owner's full
 * solved-challenges list down to it client-side (the list is already small
 * per-user; no server-side pagination needed here), then renders each match as
 * a nav row to the submission DETAIL page.
 *
 * @param props - optional className for the root element.
 */
export const ProfileChallengeManagePage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const username = useProfileUsername()
    const params = useParams<{ courseId: string }>()
    const courseSlug = params?.courseId ? String(params.courseId) : null

    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data,
        isLoading,
        error,
        mutate,
    } = useQueryUserSolvedChallengesSwr(userId)

    const [search, setSearch] = useState("")
    const [filterOpen, setFilterOpen] = useState(false)
    const [difficultyFilter, setDifficultyFilter] = useState<DifficultyFilterValue>("all")
    const [languageFilter, setLanguageFilter] = useState<LanguageFilterValue>("all")
    const [sort, setSort] = useState<SortValue>("newest")

    const allChallenges = data ?? []
    // scope down to THIS course only ΓÇö the manage page's whole reason to exist
    const courseChallenges = useMemo(
        () => allChallenges.filter((challenge) => challenge.courseSlug === courseSlug),
        [allChallenges, courseSlug],
    )
    const courseTitle = courseChallenges[0]?.courseTitle ?? null
    // how many of the two facet filters are narrowing right now (drives the funnel badge)
    const activeFacetCount = (difficultyFilter !== "all" ? 1 : 0) + (languageFilter !== "all" ? 1 : 0)
    const clearFacets = () => {
        setDifficultyFilter("all")
        setLanguageFilter("all")
    }

    // filter option pools ΓÇö only difficulties/languages actually present in this course
    const difficultyOptions = useMemo(
        () => Array.from(new Set(courseChallenges.map((challenge) => challenge.difficulty).filter((value): value is string => Boolean(value)))),
        [courseChallenges],
    )
    const languageOptions = useMemo(
        () => Array.from(new Set(courseChallenges.map((challenge) => challenge.selectedLang).filter((value): value is string => Boolean(value)))),
        [courseChallenges],
    )

    const filtered = useMemo(() => {
        const query = search.trim().toLowerCase()
        const rows = courseChallenges.filter((challenge) => {
            if (query && !challenge.title.toLowerCase().includes(query)) {
                return false
            }
            if (difficultyFilter !== "all" && challenge.difficulty !== difficultyFilter) {
                return false
            }
            if (languageFilter !== "all" && challenge.selectedLang !== languageFilter) {
                return false
            }
            return true
        })
        const sorted = [...rows]
        if (sort === "score") {
            sorted.sort((a, b) => (b.score ?? -1) - (a.score ?? -1))
        } else {
            sorted.sort((a, b) => {
                const bTime = b.passedAt ? new Date(b.passedAt).getTime() : 0
                const aTime = a.passedAt ? new Date(a.passedAt).getTime() : 0
                return bTime - aTime
            })
        }
        return sorted
    }, [courseChallenges, search, difficultyFilter, languageFilter, sort])

    const hasActiveFilter = Boolean(search.trim() || difficultyFilter !== "all" || languageFilter !== "all")

    return (
        <div className={"mx-auto flex max-w-4xl flex-col gap-6"}>
            <PageHeader
                breadcrumb={(
                    <BackLink
                        target={t("publicProfile.challengesTab.repoHeading")}
                        onPress={() => router.push(pathConfig().locale(locale).profile(username ?? undefined).challenges().build())}
                    />
                )}
                title={courseTitle ?? t("publicProfile.challengesTab.manage.title")}
                description={t("publicProfile.challengesTab.manage.description")}
            />

            {/* search + a FUNNEL popover (difficulty/language facets) + sort, one row.
                Facets live behind the funnel so the toolbar stays a single clean line
                regardless of how many facet values exist. */}
            <Cluster gap={4} principle="content-row" justify="between" align="center" classNames={["w-full"]}
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <StackH gap={4} principle="flex-action" classNames={["min-w-0", "flex-1"]}
                            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                            items={[
                                () => (
                                    <SearchInput
                                        className="min-w-0 flex-1"
                                        value={search}
                                        onValueChange={setSearch}
                                        placeholder={t("publicProfile.challengesTab.manage.searchPlaceholder")}
                                    />
                                ),
                                () => (
                                    <Popover isOpen={filterOpen} onOpenChange={setFilterOpen}>
                                        <Button
                                            isIconOnly
                                            variant="ghost"
                                            aria-label={t("publicProfile.challengesTab.manage.filterButton")}
                                            className="shrink-0"
                                        >
                                            {activeFacetCount > 0 ? (
                                                <Badge.Anchor>
                                                    <FunnelIcon className="size-5" />
                                                    <Badge size="sm" color="accent" placement="top-left">{activeFacetCount}</Badge>
                                                </Badge.Anchor>
                                            ) : (
                                                <FunnelIcon className="size-5" />
                                            )}
                                        </Button>
                                        <Popover.Content className="w-72">
                                            <Box principle="cell-pad" className="p-3"
                                                explain="Tight cell inset ΓÇö not card-padding, because this sits inside a dense table or list cell rather than a card body.">
                                                <StackV gap={4} principle="group-boundary"
                                                    explain="Section group spacing ΓÇö not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                                                    items={[
                                                        () => (
                                                            <StackV gap={4} principle="label-field"
                                                                explain="Form label above its field ΓÇö not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                                items={[
                                                                    () => <Typography type="body-xs" color="muted">{t("publicProfile.challengesTab.manage.sortHeading")}</Typography>,
                                                                    () => (
                                                                        <FlexWrapButtonRadio<SortValue>
                                                                            ariaLabel={t("publicProfile.challengesTab.manage.sortAria")}
                                                                            value={sort}
                                                                            onChange={setSort}
                                                                            items={[
                                                                                { value: "newest", content: t("publicProfile.challengesTab.manage.sortNewest") },
                                                                                { value: "score", content: t("publicProfile.challengesTab.manage.sortScore") },
                                                                            ]}
                                                                        />
                                                                    ),
                                                                ]} />
                                                        ),
                                                        ...(difficultyOptions.length > 0 ? [() => (
                                                            <StackV gap={4} principle="label-field"
                                                                explain="Form label above its field ΓÇö not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                                items={[
                                                                    () => <Typography type="body-xs" color="muted">{t("publicProfile.challengesTab.manage.difficultyHeading")}</Typography>,
                                                                    () => (
                                                                        <FlexWrapButtonRadio<DifficultyFilterValue>
                                                                            ariaLabel={t("publicProfile.challengesTab.manage.difficultyFilterAria")}
                                                                            value={difficultyFilter}
                                                                            onChange={setDifficultyFilter}
                                                                            items={[
                                                                                { value: "all", content: t("publicProfile.challengesTab.manage.allDifficulties") },
                                                                                ...difficultyOptions.map((raw) => ({
                                                                                    value: raw,
                                                                                    content: <DifficultyChip difficulty={difficultyLevel(raw) ?? "beginner"} />,
                                                                                })),
                                                                            ]}
                                                                        />
                                                                    ),
                                                                ]} />
                                                        )] : []),
                                                        ...(languageOptions.length > 0 ? [() => (
                                                            <StackV gap={4} principle="label-field"
                                                                explain="Form label above its field ΓÇö not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                                items={[
                                                                    () => <Typography type="body-xs" color="muted">{t("publicProfile.challengesTab.manage.languageHeading")}</Typography>,
                                                                    () => (
                                                                        <FlexWrapButtonRadio<LanguageFilterValue>
                                                                            ariaLabel={t("publicProfile.challengesTab.manage.languageFilterAria")}
                                                                            value={languageFilter}
                                                                            onChange={setLanguageFilter}
                                                                            items={[
                                                                                { value: "all", content: t("publicProfile.challengesTab.manage.allLanguages") },
                                                                                ...languageOptions.map((lang) => ({
                                                                                    value: lang,
                                                                                    content: <LanguageChip language={lang} />,
                                                                                })),
                                                                            ]}
                                                                        />
                                                                    ),
                                                                ]} />
                                                        )] : []),
                                                        ...(activeFacetCount > 0 ? [() => (
                                                            <Button variant="danger-soft" size="sm" className="self-start" onPress={clearFacets}>
                                                                {t("publicProfile.challengesTab.manage.clearFilters")}
                                                            </Button>
                                                        )] : []),
                                                    ]} />
                                            </Box>
                                        </Popover.Content>
                                    </Popover>
                                ),
                            ]} />
                    ),
                    () => (
                        <Typography type="body-sm" color="muted" className="shrink-0">
                            {t("publicProfile.challengesTab.manage.found", { count: filtered.length })}
                        </Typography>
                    ),
                ]} />

            <AsyncContent
                isLoading={(isLoading || !userId) && courseChallenges.length === 0}
                skeleton={(
                    <SurfaceCardList
                        isSkeleton
                        items={[0, 1, 2].map((row) => ({
                            key: `manage-skel-${row}`,
                            content: () => (
                                <StackV gap={2} principle="title-subtitle"
                                    explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                                    items={[
                                        () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                        () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                    ]} />
                            ),
                        }))}
                    />
                )}
                isEmpty={filtered.length === 0}
                emptyContent={hasActiveFilter
                    ? {
                        title: t("publicProfile.challengesTab.manage.emptyFiltered"),
                        onRetry: () => {
                            setSearch("")
                            setDifficultyFilter("all")
                            setLanguageFilter("all")
                        },
                        retryLabel: t("jobs.list.emptyFiltered.clearFilters"),
                    }
                    : {
                        title: t("publicProfile.challengesTab.empty"),
                        description: t("publicProfile.challengesTab.emptyHint"),
                    }}
                error={courseChallenges.length === 0 ? error : undefined}
                errorContent={{
                    title: t("publicProfile.loadError"),
                    onRetry: () => { void mutate() },
                    retryLabel: t("publicProfile.loadErrorRetry"),
                }}
            >
                <SurfaceCardList
                    items={filtered.map((challenge, index) => {
                        const level = difficultyLevel(challenge.difficulty)
                        const passedAt = challenge.passedAt
                            ? dayjs(challenge.passedAt).locale(locale).format("hh:mm MMMM DD, YYYY")
                            : undefined
                        const selectedLang = challenge.selectedLang
                        const score = challenge.score
                        return {
                            key: challenge.id ?? `${challenge.submissionUrl}-${index}`,
                            hover: "underline" as const,
                            href: username && challenge.id
                                ? pathConfig().locale(locale).profile(username).challenges()
                                    .course(courseSlug ?? "").submission(challenge.id).build()
                                : undefined,
                            content: () => (
                                <StackH gap={4} principle="content-row" justify="between" align="center"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={[
                                        () => (
                                            <StackV gap={2} principle="title-subtitle" classNames={["min-w-0", "flex-1"]}
                                                explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                                                items={[
                                                    () => (
                                                        <Typography type="body-sm" weight="medium" truncate className="underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">
                                                            {challenge.title}
                                                        </Typography>
                                                    ),
                                                    () => (
                                                        <Cluster gap={3} principle="chip-row" align="center"
                                                            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                            items={[
                                                                ...(level ? [() => <DifficultyChip difficulty={level} />] : []),
                                                                ...(selectedLang ? [() => <LanguageChip language={selectedLang} />] : []),
                                                                ...(passedAt ? [() => (
                                                                    <Typography type="body-xs" color="muted">
                                                                        {passedAt}
                                                                    </Typography>
                                                                )] : []),
                                                            ]} />
                                                    ),
                                                ]} />
                                        ),
                                        ...(typeof score === "number" ? [() => (
                                            <Typography
                                                type="body-xs"
                                                weight="medium"
                                                className={cn("shrink-0", scoreToneClass(score))}
                                            >
                                                {t("publicProfile.challengesTab.score", { score })}
                                            </Typography>
                                        )] : []),
                                    ]} />
                            ),
                        } satisfies SurfaceCardListItem
                    })}
                />
            </AsyncContent>
        </div>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    Typography,
    cn,
} from "@heroui/react"
import {
    useParams,
    useRouter,
} from "next/navigation"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    CheckCircleIcon,
    CircleIcon,
    RocketIcon,
    SealCheckIcon,
} from "@phosphor-icons/react"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import { pathConfig } from "@/resources/path"
import { useQueryUserCapstoneProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCapstoneProgressSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Score ΓåÆ attention colour the eye catches fast: high green, mid yellow, low red.
 * @param score - the graded score (0ΓÇô100).
 * @returns a `text-{token}` class for the score label.
 */
const scoreToneClass = (score: number): string => {
    if (score >= 90) {
        return "text-success-soft-foreground"
    }
    if (score >= 70) {
        return "text-warning-soft-foreground"
    }
    return "text-danger-soft-foreground"
}

/** Props for {@link ProfileProjectRoadmapPage}. */
export type ProfileProjectRoadmapPageProps = Record<string, never>
/**
 * `/profile/<u>/projects/<courseGlobalId>` ΓÇö the DETAIL tier of the projects
 * flow: the FULL milestone/task roadmap of ONE capstone course, no inline
 * expand cap (unlike the list's compact {@link import("../ProfileCapstone/ProjectCard").ProjectCard}
 * row). Reads the course id from the route, then filters the profile owner's
 * full `userCapstoneProgress` list down to it client-side ΓÇö the same data the
 * list already fetched, per the BE recommendation (no dedicated detail query).
 *
 * @param props - optional className for the root element.
 */
export const ProfileProjectRoadmapPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const username = useProfileUsername()
    const params = useParams<{ courseId: string }>()
    const courseGlobalId = params?.courseId ? String(params.courseId) : null

    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data: projectsData,
        isLoading,
        error: projectsError,
        mutate: reloadProjects,
    } = useQueryUserCapstoneProgressSwr(userId)

    const projects = projectsData ?? []
    // scope down to THIS course only ΓÇö the detail page's whole reason to exist
    const project = useMemo(
        () => projects.find((item) => item.courseGlobalId === courseGlobalId) ?? null,
        [projects, courseGlobalId],
    )

    // milestones ordered along the roadmap (defensive copy before sort)
    const milestones = useMemo(
        () => [...(project?.milestones ?? [])].sort((a, b) => a.position - b.position),
        [project],
    )

    const totalTasks = Math.max(project?.totalTasks ?? 0, 1)
    const percent = Math.round(((project?.completedTasks ?? 0) / totalTasks) * 100)
    const hasVerified = (project?.completedTasks ?? 0) > 0

    const resolvedLoading = (isLoading || !userId) && !projectsData
    // resolved (not loading, no error) but no match ΓåÆ "not found" empty state
    const notFound = !resolvedLoading && !projectsError && !project

    return (
        <div className={"mx-auto flex max-w-4xl flex-col gap-6"}>
            <PageHeader
                breadcrumb={(
                    <BackLink
                        target={t("publicProfile.capstone.roadmapBackToProjects")}
                        onPress={() => router.push(pathConfig().locale(locale).profile(username ?? undefined).projects().build())}
                    />
                )}
                title={project?.courseTitle ?? t("publicProfile.capstone.roadmapTitle")}
                meta={project ? (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => (
                                <StackH gap={3} principle="chip-row" align="center"
                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                    items={[
                                        ...(hasVerified ? [() => (
                                            <StatusChip
                                                tone="success"
                                                icon={SealCheckIcon}
                                            >
                                                {t("pinnedProjects.verified")}
                                            </StatusChip>
                                        )] : []),
                                        () => (
                                            <Typography type="body-xs" color="muted">
                                                {t("publicProfile.capstone.roadmapSummary", {
                                                    completedMilestones: project.completedMilestones,
                                                    totalMilestones: project.totalMilestones,
                                                    completedTasks: project.completedTasks,
                                                    totalTasks: project.totalTasks,
                                                })}
                                            </Typography>
                                        ),
                                    ]} />
                            ),
                            () => (
                                <SegmentBar
                                    hideLegend
                                    max={totalTasks}
                                    ariaLabel={`${project.courseTitle} ┬╖ ${percent}%`}
                                    segments={[
                                        {
                                            key: "verified",
                                            label: t("publicProfile.capstone.projectsHeading"),
                                            value: project.completedTasks,
                                            color: "var(--success)",
                                        },
                                    ]}
                                />
                            ),
                        ]} />
                ) : undefined}
            />

            <AsyncContent
                isLoading={resolvedLoading}
                skeleton={(
                    <SurfaceListCard>
                        {[0, 1].map((row) => (
                            <SurfaceListCardItem key={row}>
                                <StackH gap={4} principle="content-row" align="start"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={[
                                        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                        () => (
                                            <StackV gap={4} principle="label-field" classNames={["min-w-0", "flex-1"]}
                                                explain="Form label above its field ΓÇö not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                items={[
                                                    () => <Skeleton.Typography type="body-sm" width="1/3" />,
                                                    () => <Skeleton.ProgressBar />,
                                                    () => <Skeleton.Typography type="body-xs" width="2/3" />,
                                                    () => (
                                                        <StackV gap={1} principle="name-handle"
                                                            explain="Display name with handle ΓÇö not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                                            items={
                                                                [0, 1].map((task) => () => (
                                                                    <StackH key={task} gap={4} principle="content-row" align="center"
                                                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                        items={[
                                                                            () => <Skeleton className="size-5 shrink-0 rounded-full" />,
                                                                            () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                                        ]} />
                                                                ))
                                                            } />
                                                    ),
                                                ]} />
                                        ),
                                    ]} />
                            </SurfaceListCardItem>
                        ))}
                    </SurfaceListCard>
                )}
                isEmpty={notFound || (Boolean(project) && milestones.length === 0)}
                emptyContent={notFound
                    ? {
                        title: t("publicProfile.capstone.roadmapNotFound"),
                        description: t("publicProfile.capstone.roadmapNotFoundHint"),
                    }
                    : {
                        title: t("publicProfile.capstone.roadmapEmpty"),
                    }}
                error={projectsError}
                errorContent={{
                    title: t("publicProfile.capstone.loadErrorTitle"),
                    description: t("publicProfile.capstone.loadErrorDescription"),
                    onRetry: () => {
                        void reloadProjects()
                    },
                    retryLabel: t("publicProfile.capstone.loadErrorRetry"),
                }}
            >
                <SurfaceListCard>
                    {milestones.map((milestone, milestoneIndex) => (
                        <SurfaceListCardItem key={milestone.milestoneGlobalId ?? `${milestone.title}-${milestoneIndex}`}>
                            <StackH gap={4} principle="content-row" align="start"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                items={[
                                    () => (
                                        <IconTile
                                            size="sm"
                                            icon={<RocketIcon aria-hidden focusable="false" />}
                                        />
                                    ),
                                    () => (
                                        <StackV gap={4} principle="label-field" classNames={["min-w-0", "flex-1"]}
                                            explain="Form label above its field ΓÇö not title-subtitle, because the upper line labels an input rather than a heading pair."
                                            items={[
                                                () => (
                                                    <ProgressMeter
                                                        label={milestone.title}
                                                        value={milestone.passedTasks}
                                                        max={Math.max(milestone.totalTasks, 1)}
                                                        showValue
                                                    />
                                                ),
                                                () => (
                                                    <Typography type="body-xs" color="muted">
                                                        {t("publicProfile.capstone.roadmapMilestoneProgress", {
                                                            completed: milestone.passedTasks,
                                                            total: milestone.totalTasks,
                                                        })}
                                                    </Typography>
                                                ),
                                                () => (
                                                    <StackV gap={1} principle="name-handle"
                                                        explain="Display name with handle ΓÇö not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                                        items={
                                                            milestone.tasks.map((task, taskIndex) => () => (
                                                                <div
                                                                    key={task.taskGlobalId ?? `${task.title}-${taskIndex}`}
                                                                    className={cn(
                                                                        taskIndex < milestone.tasks.length - 1 && "border-b border-default",
                                                                    )}
                                                                >
                                                                    <StackH
                                                                        gap={4}
                                                                        principle="content-row"
                                                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                        align="center"
                                                                        items={[
                                                                            () => (
                                                                                task.passed ? (
                                                                                    <CheckCircleIcon aria-hidden focusable="false" className="size-5 shrink-0 text-success-soft-foreground" />
                                                                                ) : (
                                                                                    <CircleIcon aria-hidden focusable="false" className="size-5 shrink-0 text-muted-foreground" />
                                                                                )
                                                                            ),
                                                                            () => (
                                                                                <Typography
                                                                                    type="body-sm"
                                                                                    className={cn("min-w-0 flex-1 truncate", task.passed && "text-success-soft-foreground")}
                                                                                >
                                                                                    {task.title}
                                                                                </Typography>
                                                                            ),
                                                                            ...(task.passed ? [() => (
                                                                                <StackH gap={2} principle="separator-dot" classNames={["shrink-0"]}
                                                                                    explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
                                                                                    items={[
                                                                                        () => (
                                                                                            <Typography
                                                                                                type="body-xs"
                                                                                                weight="medium"
                                                                                                className={scoreToneClass(task.score)}
                                                                                            >
                                                                                                {t("publicProfile.capstone.score", { score: task.score })}
                                                                                            </Typography>
                                                                                        ),
                                                                                        ...(task.passedAt ? [() => {
                                                                                            const passedAt = task.passedAt as string | number | Date
                                                                                            return (
                                                                                                <Typography type="body-xs" color="muted">
                                                                                                    {` ┬╖ ${new Date(passedAt).toLocaleDateString(locale)}`}
                                                                                                </Typography>
                                                                                            )
                                                                                        }] : []),
                                                                                    ]} />
                                                                            )] : []),
                                                                        ]}
                                                                    />
                                                                </div>
                                                            ))
                                                        } />
                                                ),
                                            ]} />
                                    ),
                                ]} />
                        </SurfaceListCardItem>
                    ))}
                </SurfaceListCard>
            </AsyncContent>
        </div>
    )
}
